// ── END SHADOW WORLD MECHANICS ────────────────────────────────────────────────

// ── THE STALKER FLOOR — DARKNESS SWALLOWER ────────────────────────────────────
var _DARKNESS_SWALLOWER_IMG = "data:image/png;base64,";
var _stalkerActive = false;
var _stalkerMoving = false;
var _stalkerGrid = { playerX:2, playerY:2, enemyX:0, enemyY:0 };
var _stalkerEscapes = 0;
var _stalkerMaxEscapes = 3;
var _stalkerCaught = false;
var _stalkerGrowlSource = null;
var _stalkerGrowlGain = null;
var _stalkerGrowlPanner = null;

function initStalkerFloor() {
  _stalkerActive = true;
  _stalkerEscapes = 0;
  _stalkerCaught = false;
  DS.inCombat = false; // prevent enemy attacks during stalker
  _stalkerGrid.playerX = 2;
  _stalkerGrid.playerY = 2;
  var edges = [{x:0,y:0},{x:4,y:0},{x:0,y:4},{x:4,y:4},{x:2,y:0},{x:2,y:4},{x:0,y:2},{x:4,y:2}];
  var startEdge = edges[Math.floor(Math.random() * edges.length)];
  _stalkerGrid.enemyX = startEdge.x;
  _stalkerGrid.enemyY = startEdge.y;
  // Stop ALL audio — current source, ambient, howler, HTML audio
  if (AUD && AUD.currentSource) { try { AUD.currentSource.stop(); } catch(e) {} AUD.currentSource = null; }
  if (AUD && AUD.ambientSource) { try { AUD.ambientSource.stop(); } catch(e) {} AUD.ambientSource = null; }
  if (typeof _howlMusic !== 'undefined' && _howlMusic) { try { _howlMusic.stop(); } catch(e) {} _howlMusic = null; }
  if (AUD && AUD.current && AUD.tracks && AUD.tracks[AUD.current]) {
    try { AUD.tracks[AUD.current].pause(); AUD.tracks[AUD.current].currentTime = 0; } catch(e) {}
  }
  // Force AUD.current to a different value so playTrack doesn't skip it
  AUD.current = '__stalker_reset__';
  // Hide dungeon panels so no enemies can spawn
  showDgPanels(false, false, false);
  // Start stalker music after short delay — try multiple times to ensure it plays
  setTimeout(function() {
    AUD.current = null;
    // Resume audio context first (iOS requirement)
    if (AUD.ctx && AUD.ctx.state === 'suspended') {
      AUD.ctx.resume().then(function() { playTrack('shadow-stalker'); });
    } else {
      playTrack('shadow-stalker');
    }
  }, 800);
  // Retry after 2s in case first attempt failed
  setTimeout(function() {
    if (_stalkerActive && AUD.current !== 'shadow-stalker') {
      AUD.current = null;
      playTrack('shadow-stalker');
    }
  }, 2000);
  showStalkerUI();
  updateStalkerDisplay();
  setTimeout(function() { updateStalkerVisual(); }, 100);
  // Start looping growl after music starts
  setTimeout(function() { startGrowlLoop(); }, 1500);
  say('Something stirs in the darkness. The music shifts. Move carefully — the Darkness Swallower is somewhere in this room with you. It is ' + getStalkerDistance() + ' step' + (getStalkerDistance() !== 1 ? 's' : '') + ' away. Move north, south, east, or west to reach the exit.');
}

function playSwallowerFootstep() {
  if (!_stalkerActive) return;
  try {
    if (!AUD || !AUD.ctx) return;
    if (AUD.ctx.state === 'suspended') AUD.ctx.resume();
    var dir = getStalkerDirection();
    var dist = getStalkerDistance();
    var vol = Math.max(0.1, 1 - (dist * 0.12));
    var panValue = 0;
    switch(dir) {
      case 'left':   panValue = -0.8; break;
      case 'right':  panValue = 0.8;  break;
      default:       panValue = 0;    break;
    }
    var gainNode = AUD.ctx.createGain();
    gainNode.gain.value = vol * (AUD.sfxVol || 0.8);
    if (AUD.ctx.createStereoPanner) {
      var panner = AUD.ctx.createStereoPanner();
      panner.pan.value = panValue;
      gainNode.connect(panner);
      panner.connect(AUD.ctx.destination);
    } else {
      gainNode.connect(AUD.ctx.destination);
    }
    fetch(_audioUrl('monster-footstep.mp3')).then(function(r){ return r.arrayBuffer(); }).then(function(buf){
      return AUD.ctx.decodeAudioData(buf);
    }).then(function(buffer){
      if (!_stalkerActive) return;
      var source = AUD.ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(gainNode);
      source.start(0);
    }).catch(function(e){ console.warn('[DD] Swallower footstep failed:', e); });
  } catch(e) { console.warn('[DD] playSwallowerFootstep error:', e); }
}

function startGrowlLoop() {
  if (!_stalkerActive) return;
  try {
    if (!AUD || !AUD.ctx) return;
    if (AUD.ctx.state === 'suspended') AUD.ctx.resume();
    var dir = getStalkerDirection();
    var dist = getStalkerDistance();
    var vol = Math.max(0.2, 1 - (dist * 0.15));
    // Use StereoPannerNode — works reliably on iOS with headphones
    var panner = AUD.ctx.createStereoPanner ? AUD.ctx.createStereoPanner() : null;
    var panValue = 0;
    switch(dir) {
      case 'left':   panValue = -0.8; break;
      case 'right':  panValue = 0.8;  break;
      case 'ahead':  panValue = 0;    break;
      case 'behind': panValue = 0;    break;
      default:       panValue = 0;    break;
    }
    if (panner) panner.pan.value = panValue;
    var gainNode = AUD.ctx.createGain();
    gainNode.gain.value = vol * (AUD.sfxVol || 0.8);
    if (panner) {
      gainNode.connect(panner);
      panner.connect(AUD.ctx.destination);
    } else {
      gainNode.connect(AUD.ctx.destination);
    }
    _stalkerGrowlGain = gainNode;
    _stalkerGrowlPanner = panner;
    fetch(_audioUrl('monster-growl.mp3')).then(function(r){ return r.arrayBuffer(); }).then(function(buf){
      return AUD.ctx.decodeAudioData(buf);
    }).then(function(buffer){
      if (!_stalkerActive) return;
      var source = AUD.ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      source.connect(gainNode);
      source.start(0);
      _stalkerGrowlSource = source;
    }).catch(function(e){ console.warn('[DD] Growl loop failed:', e); });
  } catch(e) { console.warn('[DD] startGrowlLoop error:', e); }
}

function updateGrowlPosition() {
  if (!_stalkerActive) return;
  var dir = getStalkerDirection();
  var dist = getStalkerDistance();
  var vol = Math.max(0.2, 1 - (dist * 0.15));
  try {
    if (_stalkerGrowlPanner && _stalkerGrowlPanner.pan) {
      switch(dir) {
        case 'left':   _stalkerGrowlPanner.pan.value = -0.8; break;
        case 'right':  _stalkerGrowlPanner.pan.value = 0.8;  break;
        default:       _stalkerGrowlPanner.pan.value = 0;     break;
      }
    }
    if (_stalkerGrowlGain) _stalkerGrowlGain.gain.value = vol * (AUD.sfxVol || 0.8);
  } catch(e) {}
}

function stopGrowlLoop() {
  try { if (_stalkerGrowlSource) { _stalkerGrowlSource.stop(); _stalkerGrowlSource = null; } } catch(e) {}
  _stalkerGrowlGain = null;
  _stalkerGrowlPanner = null;
}

function getStalkerDistance() {
  var dx = Math.abs(_stalkerGrid.playerX - _stalkerGrid.enemyX);
  var dy = Math.abs(_stalkerGrid.playerY - _stalkerGrid.enemyY);
  return dx + dy;
}

function getStalkerDirection() {
  var dx = _stalkerGrid.enemyX - _stalkerGrid.playerX;
  var dy = _stalkerGrid.enemyY - _stalkerGrid.playerY;
  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx > 0 ? 'right' : 'left';
  } else {
    return dy > 0 ? 'ahead' : 'behind';
  }
}

function stalkerMove(dir) {
  if (!_stalkerActive) return;
  if (_stalkerMoving) return;
  _stalkerMoving = true;
  if (dir === 'north' && _stalkerGrid.playerY > 0) _stalkerGrid.playerY--;
  if (dir === 'south' && _stalkerGrid.playerY < 4) _stalkerGrid.playerY++;
  if (dir === 'west'  && _stalkerGrid.playerX > 0) _stalkerGrid.playerX--;
  if (dir === 'east'  && _stalkerGrid.playerX < 4) _stalkerGrid.playerX++;
  sfx('sfx-stairs');
  var dx = _stalkerGrid.playerX - _stalkerGrid.enemyX;
  var dy = _stalkerGrid.playerY - _stalkerGrid.enemyY;
  if (Math.abs(dx) >= Math.abs(dy)) {
    _stalkerGrid.enemyX += dx > 0 ? 1 : -1;
  } else {
    _stalkerGrid.enemyY += dy > 0 ? 1 : -1;
  }
  var dist = getStalkerDistance();
  var dir2 = getStalkerDirection();
  // Update growl position (already looping)
  updateGrowlPosition();
  // Play directional footstep for the Swallower
  playSwallowerFootstep();
  // Update visual for sighted players
  updateStalkerVisual();
  // Check caught FIRST
  if (dist === 0) { _stalkerMoving = false; stalkerCaught(); return; }
  // Check exit
  var atExit = _stalkerGrid.playerX === 0 || _stalkerGrid.playerX === 4 ||
               _stalkerGrid.playerY === 0 || _stalkerGrid.playerY === 4;
  if (atExit) {
    _stalkerEscapes++;
    if (_stalkerEscapes >= _stalkerMaxEscapes) { _stalkerMoving = false; stalkerEscaped(); return; }
    _stalkerGrid.playerX = 2; _stalkerGrid.playerY = 2;
    addLog('You slip away — temporarily. ' + (_stalkerMaxEscapes - _stalkerEscapes) + ' more escape' + (_stalkerMaxEscapes - _stalkerEscapes !== 1 ? 's' : '') + ' needed.');
    say('You escape — for now. ' + (_stalkerMaxEscapes - _stalkerEscapes) + ' more needed.');
    updateStalkerDisplay();
    setTimeout(function() { _stalkerMoving = false; }, 1200);
    return;
  }
  if (dist === 1) {
    addLog('💀 The Darkness Swallower is right next to you. You can hear it breathe.');
    say('It is right next to you. One step away. The darkness breathes.');
    vibe && vibe(VIBE.dreadClose);
    showStalkerFightOption();
  } else if (dist === 2) {
    var hint2 = (dir2 === 'ahead' || dir2 === 'behind') ? ' — ' + dir2 + ' of you' : '';
    addLog('⚠️ It is 2 steps away' + hint2 + '.');
    say('It is 2 steps away' + hint2 + '. Listen for the direction.');
  } else {
    var hint = (dir2 === 'ahead' || dir2 === 'behind') ? ' — ' + dir2 + ' of you' : '';
    addLog('👣 ' + dir + '. The Darkness Swallower is ' + dist + ' step' + (dist !== 1 ? 's' : '') + ' away' + hint + '.');
    say('You move ' + dir + '. It is ' + dist + ' steps away' + hint + '. Listen for its position.');
  }
  updateStalkerDisplay();
  // Unlock movement after footstep plays
  setTimeout(function() { _stalkerMoving = false; }, 1200);
}

function stalkerCaught() {
  _stalkerActive = false;
  _stalkerMoving = false;
  stopGrowlLoop();
  hideStalkerUI();
  // Restore dungeon panels
  showDgPanels(true, true, true);
  try {
    var js = new Audio(_audioUrl('jump-scare-v3.mp3'));
    js.volume = AUD ? (AUD.sfxVol || 0.8) : 0.8;
    js.play().catch(function(){});
  } catch(e) {}
  vibe && vibe(VIBE.jumpscare);
  var dmg = Math.round(DS.maxHp * 0.35);
  DS.hp = Math.max(1, DS.hp - dmg);
  updatePlayerBar();
  addLog('💀 THE DARKNESS SWALLOWER CATCHES YOU! ' + dmg + ' shadow damage!');
  say('Caught! The Darkness Swallower strikes. ' + dmg + ' damage. You barely survive.');
  setTimeout(function() { playTrack(exploTrackForFloor(DS.floor)); enterRoom(); }, 2000);
}

function stalkerEscaped() {
  _stalkerActive = false;
  _stalkerMoving = false;
  stopGrowlLoop();
  hideStalkerUI();
  // Restore dungeon panels
  showDgPanels(true, true, true);
  addLog('✨ You escaped the Darkness Swallower! Rare loot awarded.');
  say('You escaped! The Darkness Swallower retreats into the shadows. Rare loot for your survival.');
  var lootOptions = SHADOW_LOOT.filter(function(l){ return l.type === 'weapon' || l.type === 'armor'; });
  if (lootOptions.length > 0 && DS.inventory) {
    var reward = Object.assign({}, lootOptions[Math.floor(Math.random() * lootOptions.length)]);
    DS.inventory.push(reward);
    addLog('📦 Found: ' + reward.name + '!');
  }
  DS.gold += 150;
  addGlobalGold(150); // (went to the run but never to your global gold)
  updateTopBar();
  sfx('sfx-victory');
  vibe && vibe(VIBE.bossKill);
  setTimeout(function() { playTrack(exploTrackForFloor(DS.floor)); enterRoom(); }, 1500);
}

function stalkerChooseFight() {
  hideStalkerFightOption();
  _stalkerActive = false;
  _stalkerMoving = false;
  stopGrowlLoop();
  hideStalkerUI();
  showDgPanels(true, true, true);
  playTrack(battleTrack());
  DS.enemy = {
    name: 'The Darkness Swallower', icon: '🌑',
    hp: Math.round(DS.maxHp * 1.5), maxHp: Math.round(DS.maxHp * 1.5),
    atk: [Math.round((DS.atk ? DS.atk[1] : 15) * 1.2), Math.round((DS.atk ? DS.atk[1] : 15) * 1.8)],
    gold: [80, 150], isBoss: false, corruptOnHit: 2,
    desc: 'It has been waiting in this room for 3000 years. You chose to fight it. That was very brave. Possibly very stupid.'
  };
  DS.inCombat = true;
  DS.defending = false;
  addLog('⚔ You turn to face the Darkness Swallower!');
  say('You face the Darkness Swallower. It hits hard and adds 2 corruption per hit. Use Purge.');
  updateEnemyBar(); updatePlayerBar();
  setCombatBtns(true); updateSkillButtons();
}

function showStalkerUI() {
  var existing = document.getElementById('stalker-overlay');
  if (existing) existing.remove();
  var existingVis = document.getElementById('stalker-visual');
  if (existingVis) existingVis.remove();

  // Sighted players get full black screen with silhouette
  if (!_screenReaderActive) {
    var vis = document.createElement('div');
    vis.id = 'stalker-visual';
    vis.style.cssText = 'position:fixed;inset:0;background:#000;z-index:498;overflow:hidden;touch-action:none;';
    vis.innerHTML =
      // Fog/atmosphere
      '<div style="position:absolute;inset:0;background:radial-gradient(ellipse at center,#0a0005 0%,#000 70%);pointer-events:none;"></div>' +
      // The silhouette - positioned absolutely within the container
      '<img id="stalker-figure" src="' + _DARKNESS_SWALLOWER_IMG + '" ' +
        'style="position:absolute;width:80px;height:auto;opacity:0.9;bottom:20%;left:calc(50% - 40px);transition:all 0.4s ease;filter:drop-shadow(0 0 20px #660000);pointer-events:none;" ' +
        'aria-hidden="true" alt="">' +
      // Red eye pulse overlay
      '<div id="stalker-eye-pulse" style="position:absolute;width:8px;height:8px;background:radial-gradient(circle,#ff0000,#660000);border-radius:50%;opacity:0;filter:blur(2px);pointer-events:none;transition:opacity 0.3s;left:50%;bottom:40%;"></div>' +
      // Vignette
      '<div style="position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,0.8) 100%);pointer-events:none;"></div>';
    document.body.appendChild(vis);

    // Swipe camera pan
    var _swipeStartX = 0;
    var _camOffset = 0;
    vis.addEventListener('touchstart', function(e) { _swipeStartX = e.touches[0].clientX; }, {passive:true});
    vis.addEventListener('touchmove', function(e) {
      var dx = e.touches[0].clientX - _swipeStartX;
      _camOffset = Math.max(-150, Math.min(150, dx));
      updateStalkerVisual();
    }, {passive:true});
    vis.addEventListener('touchend', function() {
      _swipeStartX = 0;
      // Slowly return camera to center
      var returnInt = setInterval(function() {
        _camOffset *= 0.8;
        if (Math.abs(_camOffset) < 1) { _camOffset = 0; clearInterval(returnInt); }
        updateStalkerVisual();
      }, 50);
    }, {passive:true});
    window._stalkerCamOffset = 0;
  }

  // Controls overlay (always visible — blind and sighted)
  var ov = document.createElement('div');
  ov.id = 'stalker-overlay';
  ov.setAttribute('role', 'region');
  ov.setAttribute('aria-label', 'Stalker Floor — Darkness Swallower');
  ov.style.cssText = 'position:fixed;bottom:0;left:0;right:0;background:' + (_screenReaderActive ? '#050005' : 'rgba(0,0,0,0.85)') + ';border-top:2px solid #9966cc;padding:12px 16px;z-index:500;';
  ov.innerHTML =
    '<div id="stalker-status" style="font-family:Cinzel,serif;font-size:0.72rem;color:#cc88ff;margin-bottom:10px;text-align:center;" aria-live="assertive"></div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">' +
      '<button onclick="stalkerMove(\'north\')" style="padding:10px;background:#0a0008;border:1px solid #9966cc;color:#cc88ff;font-family:Cinzel,serif;font-size:0.7rem;cursor:pointer;" aria-label="Move north">↑ North</button>' +
      '<button onclick="stalkerMove(\'south\')" style="padding:10px;background:#0a0008;border:1px solid #9966cc;color:#cc88ff;font-family:Cinzel,serif;font-size:0.7rem;cursor:pointer;" aria-label="Move south">↓ South</button>' +
      '<button onclick="stalkerMove(\'west\')"  style="padding:10px;background:#0a0008;border:1px solid #9966cc;color:#cc88ff;font-family:Cinzel,serif;font-size:0.7rem;cursor:pointer;" aria-label="Move west">← West</button>' +
      '<button onclick="stalkerMove(\'east\')"  style="padding:10px;background:#0a0008;border:1px solid #9966cc;color:#cc88ff;font-family:Cinzel,serif;font-size:0.7rem;cursor:pointer;" aria-label="Move east">→ East</button>' +
    '</div>' +
    '<div id="stalker-fight-option" style="display:none;">' +
      '<button onclick="stalkerChooseFight()" style="width:100%;padding:10px;background:#1a0022;border:1px solid #ff4444;color:#ff8888;font-family:Cinzel,serif;font-size:0.7rem;cursor:pointer;margin-top:4px;" aria-label="Fight the Darkness Swallower">⚔ Face It</button>' +
    '</div>';
  document.body.appendChild(ov);
}

function updateStalkerVisual() {
  if (_screenReaderActive) return;
  var fig = document.getElementById('stalker-figure');
  var eyePulse = document.getElementById('stalker-eye-pulse');
  if (!fig) return;
  var dist = getStalkerDistance();
  var dir = getStalkerDirection();
  var camOffset = window._stalkerCamOffset || 0;

  // Size based on distance — closer = bigger
  var sizes = { 0:320, 1:220, 2:150, 3:100, 4:70, 5:50, 6:40 };
  var size = sizes[Math.min(dist, 6)] || 40;

  // Left/right position based on direction + camera offset
  var baseLeft = 50; // center %
  if (dir === 'left')  baseLeft = 30;
  if (dir === 'right') baseLeft = 70;
  // Apply camera pan offset
  var panPx = (window._stalkerCamOffset || 0);
  var leftPct = baseLeft + (panPx / window.innerWidth * 30);

  fig.style.width = size + 'px';
  fig.style.left = 'calc(' + leftPct + '% - ' + (size/2) + 'px)';
  fig.style.bottom = '20%';
  fig.style.opacity = Math.max(0.3, 1 - (dist * 0.1));

  // Eye pulse — brighter when closer
  if (eyePulse && dist <= 2) {
    eyePulse.style.opacity = dist === 1 ? '1' : '0.6';
    eyePulse.style.left = 'calc(' + leftPct + '% - 4px)';
    eyePulse.style.bottom = 'calc(20% + ' + (size * 0.78) + 'px)';
  } else if (eyePulse) {
    eyePulse.style.opacity = '0';
  }

  // Flicker effect when very close
  if (dist <= 1) {
    fig.style.filter = 'drop-shadow(0 0 40px #ff0000) drop-shadow(0 0 20px #660000)';
  } else {
    fig.style.filter = 'drop-shadow(0 0 20px #660000)';
  }
}

function hideStalkerUI() {
  var ov = document.getElementById('stalker-overlay');
  if (ov) ov.remove();
  var vis = document.getElementById('stalker-visual');
  if (vis) vis.remove();
}

function hideStalkerFightOption() {
  var el = document.getElementById('stalker-fight-option');
  if (el) el.style.display = 'none';
}

function showStalkerFightOption() {
  var el = document.getElementById('stalker-fight-option');
  if (el) el.style.display = '';
}

function updateStalkerDisplay() {
  var el = document.getElementById('stalker-status');
  if (!el) return;
  var dist = getStalkerDistance();
  var dir = getStalkerDirection();
  var escStr = 'Escapes: ' + _stalkerEscapes + ' / ' + _stalkerMaxEscapes;
  el.textContent = '🌑 ' + dist + ' step' + (dist !== 1 ? 's' : '') + ' away — ' + dir + '.  ' + escStr;
  el.setAttribute('aria-label', 'Darkness Swallower ' + dist + ' steps away to the ' + dir + '. ' + escStr);
}

function checkStalkerFloor() {
  if (DS.dungeon !== 'The Shadow World') return false;
  if (DS.floor < 3) return false;
  if (_stalkerActive) return false;
  if (DS.inCombat) return false;
  // Hollow Mask relic — grants immunity for N floors
  if (DS._stalkerImmunityFloors && DS._stalkerImmunityFloors > 0) {
    DS._stalkerImmunityFloors--;
    addLog('🎭 Hollow Mask hides you from the Darkness Swallower. (' + DS._stalkerImmunityFloors + ' protection floor' + (DS._stalkerImmunityFloors !== 1 ? 's' : '') + ' left)');
    return false;
  }
  if (Math.random() > 0.10) return false;
  setTimeout(function() { initStalkerFloor(); }, 800);
  return true;
}
// ── END STALKER FLOOR ─────────────────────────────────────────────────────────

function addLog(msg) {
  var log = document.getElementById('dg-combat-log');
  if (!log) return;
  var line = document.createElement('div');
  // The trailing space keeps screen readers from running lines together ("Bash!You attack").
  if (typeof _translationEnabled !== 'undefined' && _translationEnabled) {
    line.textContent = msg + ' '; // show English immediately
    log.appendChild(line);
    log.scrollTop = log.scrollHeight;
    translateText(msg).then(function(t) {
      if (t !== msg) line.textContent = t + ' ';
    });
  } else {
    line.textContent = msg + ' ';
    log.appendChild(line);
    log.scrollTop = log.scrollHeight;
  }
}

// sayLog — adds to combat log AND announces to JAWS
// Use for important mid-combat events
function sayLog(msg) {
  addLog(msg);
  say(msg);
}

// ── INVENTORY ──
function toggleInv() {
  var panel = document.getElementById('dg-inv');
  var isOpen = panel.style.display !== 'none';
  panel.style.display = isOpen ? 'none' : '';
  sfx('sfx-select');
  if (!isOpen) {
    // Sync keepable global items into DS.inventory so soul trap etc show up
    try {
      var _kt = ['soul-trap','enchanter','music-player','skill-orb','sp-potion','rune','scroll'];
      var _gi = getGlobalInventory();
      _gi.filter(function(i){ return _kt.indexOf(i.type) !== -1; }).forEach(function(ki) {
        var already = DS.inventory.some(function(di){ return di.type === ki.type && di.name === ki.name; });
        if (!already) DS.inventory.push(ki);
      });
    } catch(e2) {}
    renderInv();
    say('Inventory opened. ' + DS.inventory.length + ' items.' + (DS.inCombat ? ' Armor equipping is locked during combat.' : ''));
  } else {
    say('Inventory closed.');
  }
}

function getInvCategory(item) {
  if (item.type === 'weapon') return 'weapons';
  if (item.type === 'armor') return 'armor';
  if (['potion','elixir','sp-potion','luck-potion','fire-potion','curse-potion','swift-potion','def-potion','atk-potion',
       'cursed','mirror-flask','phantom-potion','gravity-tonic','leech-brew','rage-tonic','fog-flask',
       'time-potion','corruption-flask','love-potion'].indexOf(item.type) !== -1) return 'potions';
  if (item.type === 'material' || ['iron-scrap','bone-shard','wolf-fang','goblin-gem','frost-crystal','fire-ember','shadow-dust','void-fragment','dragon-scale'].indexOf(item.id) !== -1) return 'materials';
  // Equipment: masks, relics, unique wearable/passive items from bosses or special events
  if (item.type === 'relic' || item.type === 'mask' || (item.type === 'consumable' && item.shadowItem) || item.isEquipment) return 'equipment';
  return 'special';
}

var _invTab = 'all';
var _invSearch = '';
var _invSearchTimer = null;
var _invFavorites = [];  // array of item names that are favorited
// Same bounded-batch approach as the bestiary — a heavily-stocked inventory
// building every row as real DOM elements (each with its own tabindex and
// aria-label) at once is what makes the screen feel like it hangs, especially on
// weaker phones. Only render _invVisibleCount items; "Load More" grows it in the
// same fixed steps instead of everything appearing simultaneously.
var _invPageSize = 40;
var _invVisibleCount = 40;

function toggleFavorite(itemName) {
  var idx = _invFavorites.indexOf(itemName);
  if (idx === -1) {
    _invFavorites.push(itemName);
    say(itemName + ' added to favorites.');
  } else {
    _invFavorites.splice(idx, 1);
    say(itemName + ' removed from favorites.');
  }
  try { DDStore.setItem('dd_inv_favorites', JSON.stringify(_invFavorites)); } catch(e) {}
  renderInv();
}

function loadFavorites() {
  try { _invFavorites = _jsonParseSafe(DDStore.getItem('dd_inv_favorites'), '[]'); } catch(e) { _invFavorites = []; }
}

function autoSortInventory() {
  if (!DS.inventory) return;
  var order = { 'favorites':0, 'weapon':1, 'armor':2, 'potion':3, 'soul-trap':4, 'enchanter':5, 'rune':6, 'scroll':7, 'skill-orb':8, 'sp-potion':9, 'material':10, 'music-player':11 };
  DS.inventory.sort(function(a, b) {
    var aFav = _invFavorites.indexOf(a.name) !== -1 ? 0 : 1;
    var bFav = _invFavorites.indexOf(b.name) !== -1 ? 0 : 1;
    if (aFav !== bFav) return aFav - bFav;
    var aOrd = order[a.type] !== undefined ? order[a.type] : 99;
    var bOrd = order[b.type] !== undefined ? order[b.type] : 99;
    return aOrd - bOrd;
  });
  renderInv();
  say('Inventory sorted. Favorites first, then weapons, armor, potions, and materials.');
}
function switchInvTab(tab) {
  _invTab = tab;
  _invVisibleCount = _invPageSize;
  var tabs = ['all','favorites','weapons','potions','special','equipment','materials'];
  tabs.forEach(function(t) {
    var btn = document.getElementById('invtab-' + t);
    if (btn) {
      btn.style.background = t === tab ? '#1a1000' : '#080808';
      btn.style.borderColor = t === tab ? '#cc9944' : '#333';
      btn.style.color = t === tab ? '#cc9944' : '#555';
    }
  });
  renderInv();
}

function onInvSearch(val) {
  _invSearch = val;
  _invVisibleCount = _invPageSize;
  clearTimeout(_invSearchTimer);
  _invSearchTimer = setTimeout(function(){ renderInv(); }, 200);
}
function onInvSearchClear() {
  _invSearch = '';
  _invVisibleCount = _invPageSize;
  var inp = document.getElementById('inv-search');
  if (inp) { inp.value = ''; inp.focus(); }
  renderInv();
}

// Combine 3 elixirs (any dungeon, any type) into 1 Golden Elixir — full heal + temporary ATK buff.
function combineElixirs() {
  var elixirIndices = [];
  DS.inventory.forEach(function(item, idx) { if (item.type === 'elixir') elixirIndices.push(idx); });
  if (elixirIndices.length < 3) {
    say('You need at least 3 elixirs to combine. You have ' + elixirIndices.length + '.');
    return;
  }
  var toRemove = elixirIndices.slice(0, 3).sort(function(a, b) { return b - a; });
  toRemove.forEach(function(idx) { DS.inventory.splice(idx, 1); });
  DS.inventory.push({
    name: 'Golden Elixir', icon: '🏆', type: 'potion', heal: 9999,
    applyEffect: 'atk-boost', atkBoost: 8, boostTurns: 3,
    desc: 'A perfect elixir, brewed from three lesser ones. Fully restores HP and grants +8 ATK for 3 turns.'
  });
  try { incrementAchievementStat('elixirsCombined', 1); } catch(eAch) {}
  updateTopBar(); renderInv(); saveProgress();
  addLog('🏆 Three elixirs combine into a single Golden Elixir!');
  say('Three elixirs combined into one Golden Elixir. It fully restores HP and boosts attack when used.');
  setEvent('good', '🏆 The elixirs swirl together and settle into something new — a Golden Elixir, gleaming faintly.');
}

function renderInv() {
  var grid = document.getElementById('dg-inv-grid');
  grid.innerHTML = '';

  // ── Build tab bar into persistent container (only once) ──
  var tabContainer = document.getElementById('dg-inv-tabs');
  if (tabContainer && !tabContainer.dataset.built) {
    tabContainer.dataset.built = '1';
    var tabs = [
      { id:'all',       label:'All' },
      { id:'favorites', label:'Fav' },
      { id:'weapons',   label:'Weapons' },
      { id:'armor',     label:'Armor' },
      { id:'potions',   label:'Potions' },
      { id:'special',   label:'Special' },
      { id:'equipment', label:'Equipment' },
      { id:'materials', label:'Materials' },
    ];
    tabs.forEach(function(t) {
      var btn = document.createElement('button');
      btn.id = 'invtab-' + t.id;
      btn.textContent = t.label;
      btn.setAttribute('aria-label', t.label + ' tab');
      btn.style.cssText = 'padding:5px 8px;background:#080808;border:1px solid #333;color:#555;font-family:Cinzel,serif;font-size:0.58rem;cursor:pointer;border-radius:2px;letter-spacing:0.05em;margin-bottom:4px;';
      btn.onclick = (function(tid){ return function(){ switchInvTab(tid); }; })(t.id);
      tabContainer.appendChild(btn);
    });
  }
  // Update tab highlight states without rebuilding
  var allTabIds = ['all','favorites','weapons','armor','potions','special','equipment','materials'];
  allTabIds.forEach(function(t) {
    var btn = document.getElementById('invtab-' + t);
    if (btn) {
      btn.style.background = t === _invTab ? '#1a1000' : '#080808';
      btn.style.borderColor = t === _invTab ? '#cc9944' : '#333';
      btn.style.color = t === _invTab ? '#cc9944' : '#555';
    }
  });

  // Show equipped items in weapons tab or all tab
  if (_invTab === 'all' || _invTab === 'weapons') {
    if (DS.equippedWeapon || DS.equippedArmor) {
      var eqHeader = document.createElement('div');
      eqHeader.style.cssText = 'font-family:Cinzel,serif;font-size:0.6rem;letter-spacing:0.3em;color:var(--gold-dim);margin-bottom:6px;margin-top:4px;';
      eqHeader.textContent = 'EQUIPPED';
      grid.appendChild(eqHeader);
      if (DS.equippedWeapon) {
        var w = DS.equippedWeapon;
        var wrow = document.createElement('div');
        wrow.style.cssText = 'display:flex;align-items:center;gap:8px;background:#1a1200;border:1px solid var(--gold-dim);padding:8px 12px;margin-bottom:4px;';
        wrow.setAttribute('tabindex','0');
        wrow.setAttribute('aria-label','Equipped weapon: '+w.name+' Level '+(w.level||1)+'. Attack '+getWeaponAtk(w).join(' to ')+'. Press Unequip to remove.');
        wrow.innerHTML = '<span style="flex:1;font-family:Cinzel,serif;font-size:0.72rem;color:var(--gold);" aria-hidden="true">'+w.icon+' '+w.name+' Lv.'+(w.level||1)+' · ATK '+getWeaponAtk(w).join('-')+'</span>';
        var uwBtn = document.createElement('button');
        uwBtn.className='btn-ghost'; uwBtn.style.cssText='padding:3px 8px;font-size:0.62rem;';
        uwBtn.textContent='Unequip'; uwBtn.setAttribute('aria-label','Unequip '+w.name);
        uwBtn.onclick=function(){ unequipWeapon(); };
        wrow.appendChild(uwBtn); grid.appendChild(wrow);
      }
      if (DS.equippedArmor) {
        var a = DS.equippedArmor;
        var arow = document.createElement('div');
        arow.style.cssText = 'display:flex;align-items:center;gap:8px;background:#0a1220;border:1px solid #334;padding:8px 12px;margin-bottom:6px;';
        arow.setAttribute('tabindex','0');
        arow.setAttribute('aria-label','Equipped armor: '+a.name+' Level '+(a.level||1)+'. Defense plus '+getArmorDef(a)+'. Press Unequip to remove.');
        arow.innerHTML = '<span style="flex:1;font-family:Cinzel,serif;font-size:0.72rem;color:#88aaff;" aria-hidden="true">'+a.icon+' '+a.name+' Lv.'+(a.level||1)+' · DEF +'+getArmorDef(a)+'</span>';
        var uaBtn = document.createElement('button');
        uaBtn.className='btn-ghost'; uaBtn.style.cssText='padding:3px 8px;font-size:0.62rem;';
        uaBtn.textContent='Unequip'; uaBtn.setAttribute('aria-label','Unequip '+a.name);
        uaBtn.onclick=function(){ unequipArmor(); };
        arow.appendChild(uaBtn); grid.appendChild(arow);
      }
      var divider = document.createElement('div');
      divider.style.cssText = 'font-family:Cinzel,serif;font-size:0.6rem;letter-spacing:0.3em;color:var(--gold-dim);margin-bottom:6px;margin-top:4px;';
      divider.textContent = 'INVENTORY';
      grid.appendChild(divider);
    }
  }

  // Potions tab: offer to combine 3 elixirs into 1 Golden Elixir once you have enough
  if (_invTab === 'potions') {
    var _elixirCount = DS.inventory.filter(function(i) { return i.type === 'elixir'; }).length;
    if (_elixirCount >= 3) {
      var combineBtn = document.createElement('button');
      combineBtn.className = 'btn-ghost';
      combineBtn.style.cssText = 'width:100%;padding:8px;margin-bottom:8px;font-size:0.68rem;border-color:#cc9944;color:#ffdd66;';
      combineBtn.textContent = '🏆 Combine 3 Elixirs into a Golden Elixir';
      combineBtn.setAttribute('aria-label', 'Combine three elixirs into one Golden Elixir. You have ' + _elixirCount + ' elixirs.');
      combineBtn.onclick = function() { combineElixirs(); };
      grid.appendChild(combineBtn);
    }
  }

  // Filter by tab AND search, sort favorites to top
  var filteredItems = DS.inventory.filter(function(item) {
    var isFav = _invFavorites.indexOf(item.name) !== -1;
    var tabMatch = _invTab === 'all'
      || (_invTab === 'favorites' && isFav)
      || (_invTab !== 'favorites' && getInvCategory(item) === _invTab);
    var searchMatch = !_invSearch || (item.name || '').toLowerCase().indexOf(_invSearch.toLowerCase()) !== -1 || (item.desc || '').toLowerCase().indexOf(_invSearch.toLowerCase()) !== -1;
    return tabMatch && searchMatch;
  });
  filteredItems.sort(function(a, b) {
    var aF = _invFavorites.indexOf(a.name) !== -1 ? 0 : 1;
    var bF = _invFavorites.indexOf(b.name) !== -1 ? 0 : 1;
    return aF - bF;
  });
  // Announce search results to screen reader
  if (_invSearch) {
    var resultCount = filteredItems.length;
    var resultAnnounce = document.getElementById('inv-search-announce');
    if (!resultAnnounce) {
      resultAnnounce = document.createElement('div');
      resultAnnounce.id = 'inv-search-announce';
      resultAnnounce.setAttribute('aria-live', 'polite');
      resultAnnounce.style.cssText = 'font-family:Cinzel,serif;font-size:0.62rem;color:#666;margin-bottom:6px;';
      grid.appendChild(resultAnnounce);
    }
    resultAnnounce.textContent = resultCount + ' item' + (resultCount === 1 ? '' : 's') + ' found for "' + _invSearch + '"';
  }

  if (filteredItems.length === 0 && DS.inventory.length === 0) {
    var empty = document.createElement('span');
    empty.className = 'dg-inv-empty';
    empty.textContent = 'Your satchel is empty.';
    grid.appendChild(empty); return;
  }
  if (filteredItems.length === 0) {
    var empty2 = document.createElement('span');
    empty2.className = 'dg-inv-empty';
    empty2.textContent = 'Nothing in this category.';
    grid.appendChild(empty2); return;
  }

  // Stack identical items by name — group them so screen readers don't get 59 enchanter rows
  var stackMap = {};
  var stackOrder = [];
  filteredItems.forEach(function(item) {
    // Weapons and armor are never stacked (each has unique level/stats)
    if (item.type === 'weapon' || item.type === 'armor') {
      var uid = item.name + '__' + (item.level||0) + '__' + Math.random();
      stackMap[uid] = { item: item, count: 1, indices: [DS.inventory.indexOf(item)] };
      stackOrder.push(uid);
    } else {
      var key = item.name;
      if (!stackMap[key]) {
        stackMap[key] = { item: item, count: 0, indices: [] };
        stackOrder.push(key);
      }
      stackMap[key].count++;
      stackMap[key].indices.push(DS.inventory.indexOf(item));
    }
  });
  var stackedEntries = stackOrder.map(function(k) { return stackMap[k]; });
  var visibleEntries = stackedEntries.slice(0, _invVisibleCount);
  visibleEntries.forEach(function(entry) {
    var item = entry.item;
    var count = entry.count;
    var i = entry.indices[0]; // index of first instance for use/drop
    var isUsable = item.type === 'potion' || item.type === 'elixir' || item.type === 'enchanter' || item.type === 'music-player' || item.type === 'luck-potion' || item.type === 'fire-potion' || item.type === 'curse-potion' || item.type === 'swift-potion' || item.type === 'def-potion' || item.type === 'atk-potion' || item.type === 'cursed' || item.type === 'rune' || item.type === 'scroll' || item.type === 'skill-orb' || item.type === 'soul-trap' || item.type === 'sp-potion' || item.type === 'gamblers-spirit' || item.type === 'mirror-flask' || item.type === 'phantom-potion' || item.type === 'gravity-tonic' || item.type === 'leech-brew' || item.type === 'rage-tonic' || item.type === 'fog-flask' || item.type === 'time-potion' || item.type === 'corruption-flask' || item.type === 'love-potion' || item.type === 'consumable' || item.type === 'seasonal-buff' || item.type === 'cannon' || item.isWhisperMusicBox || item.isFirework;
    var isRelic = item.type === 'relic';
    var isEquippable = item.isEquippable && (item.type === 'weapon' || item.type === 'armor');
    var row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;background:var(--bg-stone);border:1px solid var(--border-dim);padding:8px 12px;margin-bottom:6px;';
    row.setAttribute('tabindex','0');
    var lvlStr = item.level ? ' Level ' + item.level : '';
    var statStr = item.type==='weapon' ? ' Attack ' + getWeaponAtk(item).join(' to ') : item.type==='armor' ? ' Defense plus ' + getArmorDef(item) : '';
    var countStr = (count > 1) ? ' You have ' + count + '.' : '';
    var actionStr = isEquippable ? ' Press Equip to equip.' : isUsable ? ' Press Use to consume one.' : ' Press Drop to discard.';
    row.setAttribute('aria-label', item.name + lvlStr + statStr + countStr + '. ' + (item.desc||'') + actionStr);
    var info = document.createElement('span');
    info.style.cssText = 'flex:1;font-family:Cinzel,serif;font-size:0.72rem;color:var(--text-secondary);';
    var rarDisp = item.raritySymbol ? ' ' + item.raritySymbol : '';
    var durDisp = (item.type === 'weapon' && item.durability !== undefined && item.durability < 100) ? ' [' + getDurabilityLabel(item.durability).label + ']' : '';
    var countDisp = (count > 1) ? ' (x' + count + ')' : '';
    info.textContent = (item.icon||'') + ' ' + item.name + rarDisp + countDisp + (item.level ? ' Lv.' + item.level : '') + statStr + durDisp;
    if (item.rarityColor) info.style.color = item.rarityColor;
    else if (item.type === 'weapon' && item.durability !== undefined && item.durability < 40) info.style.color = getDurabilityLabel(item.durability).color;
    info.setAttribute('aria-hidden','true');
    row.appendChild(info);
    // Details button
    if (item.desc) {
      var detBtn = document.createElement('button');
      detBtn.type = 'button';
      detBtn.className = 'btn-ghost';
      detBtn.style.cssText = 'padding:3px 8px;font-size:0.6rem;color:#666;border-color:#222;';
      detBtn.textContent = '?';
      detBtn.setAttribute('aria-label', 'Details for ' + item.name + ': ' + item.desc);
      detBtn.onclick = (function(it, r) { return function() {
        var existing = r.querySelector('.inv-desc-panel');
        if (existing) { existing.remove(); detBtn.textContent = '?'; return; }
        var descPanel = document.createElement('div');
        descPanel.className = 'inv-desc-panel';
        descPanel.style.cssText = 'width:100%;margin-top:6px;padding:8px;background:#050505;border:1px solid #222;font-family:Cinzel,serif;font-size:0.65rem;color:#888;line-height:1.7;';
        descPanel.textContent = it.desc;
        descPanel.setAttribute('role', 'note');
        r.style.flexWrap = 'wrap';
        r.appendChild(descPanel);
        detBtn.textContent = '▲';
        say(it.name + '. ' + it.desc);
      }; })(item, row);
      row.appendChild(detBtn);
    }
    if (isEquippable) {
      var eBtn = document.createElement('button');
      eBtn.className = 'btn-ghost';
      eBtn.style.cssText = 'padding:3px 10px;font-size:0.65rem;border-color:var(--gold-dim);color:var(--gold-dim);';
      eBtn.textContent = 'Equip';
      eBtn.setAttribute('aria-label', 'Equip ' + item.name);
      eBtn.onclick = (function(it){ return function(){
        if (it.type === 'weapon') equipWeapon(it);
        else equipArmor(it);
      }; })(item);
      row.appendChild(eBtn);
    } else if (isUsable) {
      var uBtn = document.createElement('button');
      uBtn.className = 'btn-gold';
      uBtn.style.cssText = 'padding:3px 10px;font-size:0.65rem;';
      uBtn.textContent = 'Use';
      uBtn.setAttribute('aria-label', 'Use ' + item.name);
      uBtn.onclick = (function(idx2){ return function(){ useItem(idx2); }; })(i);
      row.appendChild(uBtn);
    } else if (isRelic) {
      var rBtn = document.createElement('button');
      rBtn.className = 'btn-ghost';
      rBtn.style.cssText = 'padding:3px 10px;font-size:0.65rem;opacity:0.6;cursor:default;';
      rBtn.textContent = 'Passive';
      rBtn.setAttribute('aria-label', item.name + ' — passive relic, always active');
      rBtn.disabled = true;
      row.appendChild(rBtn);
    } else {
      var dBtn = document.createElement('button');
      dBtn.className = 'btn-ghost';
      dBtn.style.cssText = 'padding:3px 10px;font-size:0.65rem;';
      dBtn.textContent = 'Drop';
      dBtn.setAttribute('aria-label', 'Drop ' + item.name);
      dBtn.onclick = (function(idx2){ return function(){
        DS.inventory.splice(idx2,1);
        renderInv();
        say('Item dropped.');
      }; })(i);
      row.appendChild(dBtn);
    }
    // Favorite star button on every item
    var favBtn = document.createElement('button');
    favBtn.type = 'button';
    var isFav = _invFavorites.indexOf(item.name) !== -1;
    favBtn.textContent = isFav ? '★' : '☆';
    favBtn.setAttribute('aria-label', (isFav ? 'Remove from favorites: ' : 'Add to favorites: ') + item.name);
    favBtn.style.cssText = 'padding:3px 7px;background:none;border:1px solid #2a2a2a;color:' + (isFav?'#ffcc00':'#444') + ';font-size:0.75rem;cursor:pointer;margin-left:2px;flex-shrink:0;';
    favBtn.onclick = (function(n){ return function(e){ e.stopPropagation(); toggleFavorite(n); }; })(item.name);
    row.appendChild(favBtn);
    grid.appendChild(row);
  });

  if (stackedEntries.length > visibleEntries.length) {
    var invLoadMoreBtn = document.createElement('button');
    invLoadMoreBtn.type = 'button';
    invLoadMoreBtn.className = 'btn-ghost';
    invLoadMoreBtn.style.cssText = 'width:100%;margin-top:8px;padding:10px;font-family:Cinzel,serif;font-size:0.68rem;';
    var invRemaining = stackedEntries.length - visibleEntries.length;
    invLoadMoreBtn.textContent = 'Load More (' + invRemaining + ' remaining)';
    invLoadMoreBtn.setAttribute('aria-label', 'Load ' + Math.min(_invPageSize, invRemaining) + ' more items. ' + invRemaining + ' remaining.');
    invLoadMoreBtn.onclick = function() {
      _invVisibleCount += _invPageSize;
      renderInv();
      var firstNew = grid.children[visibleEntries.length];
      if (firstNew) firstNew.focus();
    };
    grid.appendChild(invLoadMoreBtn);
  }
}

function useItem(i) {
  // Scrolls bought without a Spell Book (or dropped) were "spell-scroll" items
  // that nothing knew how to read; they are ordinary spell scrolls.
  if (DS.inventory && DS.inventory[i] && DS.inventory[i].type === 'spell-scroll') DS.inventory[i].type = 'scroll';
  var item = DS.inventory[i];
  if (item.isInsanityPotion) { useInsanityPotion(); DS.inventory.splice(DS.inventory.indexOf(item),1); renderInv(); return; }
  if (item.type === 'consumable' && item.shadowItem === 'shapeshifterMask') {
    if (!DS.inCombat || !DS.enemy) {
      say('The Mask can only be used in combat — face an enemy first.');
      return;
    }
    if (DS._maskUsedThisRun) {
      say('The Mask has already been used this run. Its power is spent.');
      return;
    }
    var e = DS.enemy;
    var ability = null;
    var abilityMsg = '';
    if (e.immuneFirstHit)  { DS._maskImmune = true;  ability = 'immunity to first hit'; abilityMsg = 'You are now immune to the next hit this combat.'; }
    else if (e.corruptOnHit) { DS._maskCorrupt = true; DS._maskCorruptStacks = e.corruptOnHit; ability = 'corruption on hit'; abilityMsg = 'Your next attack deals ' + (10 * e.corruptOnHit) + ' extra damage.'; }
    else if (e.fearHowl)   { DS._maskFear = true;    ability = 'fear howl'; abilityMsg = 'The enemy is filled with fear — their damage is reduced 20% for 3 turns.'; DS.enemyFearTurns = 3; }
    else if (e.twiceDead)  { DS._maskRevive = true;  ability = 'second life'; abilityMsg = 'You will return at 50% HP if you die this combat. Once.'; }
    else if (e.grows)      { DS._maskGrow = true;    ability = 'growing power'; abilityMsg = 'You gain +4 ATK every turn for the rest of this combat.'; }
    else if (e.dodgeEvery) { DS._maskDodge = true;   ability = 'phase dodge'; abilityMsg = 'You will dodge every other hit this combat.'; }
    else if (e.corruptWeb) { DS._maskWeb = true;     ability = 'void web'; abilityMsg = 'You weave a shadow web — the enemy takes 8 damage every turn until combat ends.'; }
    else if (e.reflection) { DS._maskReflect = true; ability = 'reflection'; abilityMsg = 'The enemy\'s next attack will be reflected back at them for full damage.'; }
    else if (e.lurkerHide) { DS._maskLurker = true;  ability = 'lurker strike'; abilityMsg = 'Your next attack is a guaranteed critical hit dealing 2.5x damage.'; }
    else if (e.mimicSurprise) { DS._maskMimic = true; ability = 'mimic surprise'; abilityMsg = 'Your next attack deals double damage — the enemy never saw it coming.'; }
    else if (e.shadowCommand) { DS._maskCommand = true; ability = 'shadow command'; abilityMsg = 'You command the shadows — your ATK is increased by 15% for the rest of this combat.'; }
    else if (e.spiritOnly) { DS._maskSpirit = true;  ability = 'spirit form'; abilityMsg = 'You enter spirit form — you take half damage from all physical attacks this combat.'; }
    else { ability = 'shadow essence'; abilityMsg = 'The Mask absorbs the enemy\'s shadow essence — you heal 30 HP.'; DS.hp = Math.min(DS.maxHp, DS.hp + 30); updatePlayerBar(); }

    DS._maskUsedThisRun = true;
    DS.inventory.splice(i, 1);
    renderInv(); saveProgress();
    addLog('🎭 Shapeshifter\'s Mask — you copy: ' + ability + '! ' + abilityMsg);
    say('Mask used. You copied ' + ability + '. ' + abilityMsg);
    setEvent('good', '🎭 The Mask melts into your face. For a moment you are something else entirely. You copy: ' + ability + '.');
    return;
  }
  if (item.type === 'consumable' && item.shadowItem === 'mirrorFragment') {
    if (!DS._shadowCorruption || DS._shadowCorruption === 0) {
      say('No corruption to purge. The Mirror Fragment glows faintly and waits.');
      return;
    }
    var cleared = DS._shadowCorruption;
    DS._shadowCorruption = 0;
    DS.inventory.splice(i, 1);
    updateShadowCorruptionDisplay();
    updateTopBar(); renderInv(); saveProgress();
    addLog('🪞 Mirror Fragment shattered — all ' + cleared + ' corruption stack' + (cleared > 1 ? 's' : '') + ' purged instantly!');
    say('Mirror Fragment used. All corruption cleared. The shard is gone.');
    setEvent('good', '🪞 The Mirror Fragment shatters in your hand. The corruption inside you fractures with it. ' + cleared + ' stack' + (cleared > 1 ? 's' : '') + ' purged.');
    return;
  }
  if (item.isWhisperMusicBox) {
    DS.inventory.splice(i, 1);
    renderInv(); saveProgress();
    playTrack('music-box');
    sfx('sfx-unlock');
    addLog('🎵 You open the Music Box. The melody plays. The corruption recedes.');
    say('Music Box used. Corruption cleared.');
    setEvent('good', '🎵 The melody plays. The corruption inside you fades to nothing.');
    _corruption = 0;
    updateCorruptionBar();
    setTimeout(function() {
      var mbTrack = AUD.tracks['music-box'];
      if (mbTrack) { try { mbTrack.pause(); mbTrack.currentTime = 0; } catch(e) {} }
    }, 5000);
    return;
  }
  if (item.isFirework) {
    if (!DS.inCombat || !DS.enemy) {
      say('Fireworks can only be used in combat — face an enemy first.');
      return;
    }
    useFirework(i);
    return;
  }
  if (item.type === 'elixir') {
    var elixHeal = Math.round(DS.maxHp * item.healPct);
    if (DS.hp >= DS.maxHp) { say('Your health is already full. Save the elixir for when you need it.'); return; }
    DS.hp = Math.min(DS.maxHp, DS.hp + elixHeal);
    DS.inventory.splice(i, 1);
    try { incrementAchievementStat('elixirsUsed', 1); } catch(eAch) {}
    updatePlayerBar(); updateTopBar(); renderInv(); saveProgress();
    addLog(item.icon + ' ' + item.name + ' — restored ' + elixHeal + ' HP!');
    say('Elixir used. ' + item.name + '. Restored ' + elixHeal + ' HP. Current HP: ' + DS.hp + ' of ' + DS.maxHp + '.');
    setEvent('good', item.icon + ' You uncork the ' + item.name + ' and drink deep. +' + elixHeal + ' HP. The warmth spreads through you instantly.');
    return;
  }
  if (item.type === 'potion') {
    // Handle full restore (Elixir of Life)
    if (item.heal >= 9999) {
      DS.hp = DS.maxHp;
      if (item.restoreSP) DS.sp = DS.maxSp;
      DS.inventory.splice(i, 1);
      if (item.name === 'Golden Elixir') { try { incrementAchievementStat('elixirsUsed', 1); } catch(eAch2) {} }
      updateTopBar(); renderInv(); saveProgress();
      updatePlayerBar();
      say('Used ' + item.name + '. Fully restored!');
      setEvent('good', '✨ ' + item.name + '. You feel completely restored.');
      try { applyPotionEffect(item); } catch(e2) {}
      return;
    }
    if (DS.hp >= DS.maxHp && !item.applyEffect) { say('Your health is already full.'); return; }
    // Cursed Day — potions cannot be used in combat (never checked)
    if (DS.dailyChallenge === 'cursedDay' && DS.inCombat && item.heal > 0) { say('Cursed Day — potions cannot be used in combat.'); return; }
    // Freedom Potion — debuff immunity for 3 turns (never given)
    if (item.debuffImmune) { fxGet().debuffTurns = item.debuffImmune; DS.frozen = false; DS.trapDoT = null; addLog('🔵 Immune to debuffs for ' + item.debuffImmune + ' turns.'); }
    var heal = item.heal > 0 ? Math.round((item.heal || 40) * DS.potionMult * (DS._brewmaster ? 2 : 1) * weatherPotionMult()) : 0;
    if (heal > 0 && isWhisperForest() && _corruption > 0) { reduceCorruption(10); addLog('🌲 The potion pushes the corruption back 10%.'); }
    if (heal > 0) DS.hp = Math.min(DS.maxHp, DS.hp + heal);
    DS.inventory.splice(i, 1);
    DS.usedPotion = true;
    // Apply special alchemy effects
    try { applyPotionEffect(item); } catch(e2) {}
    say('Used ' + item.name + '.' + (heal > 0 ? ' Restored ' + heal + ' HP. Current HP: ' + DS.hp + ' of ' + DS.maxHp + '.' : ''));
    setEvent('good', 'You drink the ' + item.name + '.' + (heal > 0 ? ' +' + heal + ' HP.' : ' Something stirs.'));
    updateTopBar(); renderInv(); saveProgress();
  } else if (item.type === 'sp-potion') {
    var spGain = Math.round((item.sp || 15) * DS.potionMult);
    DS.sp = Math.min(DS.maxSp, DS.sp + spGain);
    DS.inventory.splice(i, 1);
    say('Used ' + item.name + '. Restored ' + spGain + ' SP. Current SP: ' + DS.sp + ' of ' + DS.maxSp + '.');
    setEvent('good', 'You drink the ' + item.name + '. Arcane energy surges. +' + spGain + ' SP.');
    updateTopBar(); renderInv(); saveProgress();
  } else if (item.type === 'lore-fragment') {
    // Open the fragment reader
    openLoreFragment(item);
    return;
  } else if ((item.type === 'def-potion' || item.type === 'atk-potion') && item.special === 'crit') {
    // Shadow Oil — its onUse handler never ran (and is lost when the bag is saved)
    DS.markedKill = true;
    DS.inventory.splice(i, 1);
    setEvent('good', 'Shadow Oil applied. Next attack guaranteed critical!');
    say('Shadow Oil. Next attack is a guaranteed critical hit.');
    renderInv(); saveProgress();
  } else if (item.type === 'def-potion' || item.type === 'atk-potion') {
    // Potions that say "for 3 turns" now last 3 turns; before, every one of
    // them added to your stats for the whole run (and the loot table's
    // Defense Potion's bonus field was never read).
    var isAtk = item.type === 'atk-potion';
    var amt = isAtk ? (item.atk || item.bonus || 4) : (item.def || item.bonus || 3);
    var potTurns = item.turns || item.duration || 0;
    DS.inventory.splice(i, 1);
    if (potTurns > 0) {
      fxTempStat(isAtk ? 'atk' : 'def', amt, potTurns);
      say('Used ' + item.name + '. +' + amt + (isAtk ? ' attack' : ' defense') + ' for ' + potTurns + ' turns.');
      setEvent('good', item.name + ' consumed. +' + amt + (isAtk ? ' attack' : ' defense') + ' for ' + potTurns + ' turns.');
    } else {
      if (isAtk) DS.atkBonus += amt; else DS.defBonus += amt;
      say('Used ' + item.name + '. +' + amt + (isAtk ? ' attack' : ' defense') + ' for the rest of this run.');
      setEvent('good', item.name + ' consumed. +' + amt + (isAtk ? ' attack' : ' defense') + ' for the rest of this run.');
    }
    updateTopBar(); renderInv(); saveProgress();
  } else if (item.type === 'warding-bell') {
    DS._wardingBellCharges = (DS._wardingBellCharges || 0) + 1;
    DS.inventory.splice(i, 1);
    say('Warding Bell attuned. It will ring out and warn you the next time you search a room with a trap.');
    setEvent('good', '🔔 The Warding Bell hums softly, attuned and waiting.');
    renderInv(); saveProgress();
  } else if (item.type === 'cursed') {
    DS.inventory.splice(i, 1);
    var roll = Math.floor(Math.random() * 6);
    var cursedMsg = '';
    if (roll === 0) { DS.hp = Math.min(DS.maxHp, DS.hp + 60); cursedMsg = 'Massive heal! +60 HP. Lucky.'; }
    else if (roll === 1) { DS.hp = Math.max(1, DS.hp - 30); cursedMsg = 'Burns! -30 HP. Unlucky.'; }
    else if (roll === 2) { DS.sp = Math.min(DS.maxSp, DS.sp + 25); cursedMsg = 'SP surge! +25 SP.'; }
    else if (roll === 3) { DS.atkBonus += 6; cursedMsg = 'Rage! +6 attack permanently this run.'; }
    else if (roll === 4) { DS.defBonus = Math.max(0, DS.defBonus - 2); DS.hp = Math.max(1,DS.hp-15); cursedMsg = 'Weakness! -2 defense, -15 HP.'; }
    else { DS.gold += 40; addGlobalGold(40); cursedMsg = 'Gold appears from nowhere. +40 gold.'; }
    say('Cursed Vial consumed. ' + cursedMsg);
    setEvent(roll <= 0 || roll === 2 || roll === 3 || roll === 5 ? 'good' : 'bad',
      'The Cursed Vial shatters. ' + cursedMsg);
    updateTopBar(); updatePlayerBar(); renderInv(); saveProgress();
  } else if (item.type === 'luck-potion') {
    DS._luckPotionKills = 3; DS._luckPotionMult = 2;
    DS.inventory.splice(i, 1);
    say('Lucky Potion used. Next 3 kills drop double gold.');
    setEvent('good', '🍀 Lucky Potion — the next 3 enemies drop double gold!');
    renderInv(); saveProgress();
  } else if (item.type === 'fire-potion') {
    var fe = DS.enemy;
    if (!fe) { say('No enemy to target. Use this in combat.'); return; }
    var fireDmg = Math.round((fe.maxHp || fe.hp) * 0.40);
    fe.hp = Math.max(0, fe.hp - fireDmg);
    DS.inventory.splice(i, 1);
    updateEnemyBar(); sfx('sfx-trap');
    addLog('🔥 Fire Potion! ' + fireDmg + ' fire damage — ignores all defense!');
    say('Fire Potion! ' + fireDmg + ' fire damage to ' + fe.name + '.');
    setEvent('good', '🔥 The Fire Potion shatters on ' + fe.name + '. ' + fireDmg + ' fire damage!');
    renderInv(); saveProgress();
    if (fe.hp <= 0) { setTimeout(function(){ enemyDead(); }, 300); return; }
    setCombatBtns(true); updateSkillButtons();
  } else if (item.type === 'curse-potion') {
    var ce = DS.enemy;
    if (!ce) { say('No enemy to target. Use this in combat.'); return; }
    if (!ce._cursed) ce._preCurseAtk = ce.atk.slice();
    ce.atk = [Math.round(ce.atk[0]*0.5), Math.round(ce.atk[1]*0.5)];
    ce._cursed = 3;
    DS.inventory.splice(i, 1);
    addLog('☠️ Curse Potion! ' + ce.name + ' attack halved for 3 turns.');
    say('Curse Potion! ' + ce.name + ' weakened for 3 turns.');
    setEvent('good', '☠️ ' + ce.name + ' is cursed. Their attack is halved for 3 turns.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();
  } else if (item.type === 'swift-potion') {
    DS._swiftPotion = 2;
    DS.inventory.splice(i, 1);
    say('Swift Potion used. Flee is guaranteed for 2 turns.');
    setEvent('good', '💨 Swift Potion — you move like a ghost. Flee guaranteed for 2 turns.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'mirror-flask') {
    if (!DS.inCombat) { say('Use this in combat.'); return; }
    DS._mirrorFlask = true;
    DS.inventory.splice(i, 1);
    addLog('🪞 Mirror Flask! The next hit the enemy deals will be reflected back at them.');
    say('Mirror Flask active. Next enemy hit will be reflected back.');
    setEvent('good', '🪞 Mirror Flask shattered. The next attack against you will be turned back on your enemy.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'phantom-potion') {
    if (!DS.inCombat) { say('Use this in combat.'); return; }
    DS._phantomTurns = item.phantomTurns || 2; // brewed numbers (an Alchemist's are stronger)
    DS.inventory.splice(i, 1);
    addLog('👻 Phantom Potion! You become untargetable for 2 turns. Enemy attacks pass through you.');
    say('Phantom Potion active. Untargetable for 2 turns.');
    setEvent('good', '👻 Phantom Potion — for 2 turns you are untouchable.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'gravity-tonic') {
    var gte = DS.enemy;
    if (!gte) { say('No enemy to target.'); return; }
    DS._gravityTurns = item.gravityTurns || 3;
    DS.inventory.splice(i, 1);
    addLog('🌀 Gravity Tonic! ' + gte.name + ' ATK drops to 1 for 3 turns.');
    say('Gravity Tonic! Enemy ATK reduced to 1 for 3 turns.');
    setEvent('good', '🌀 The Gravity Tonic crushes ' + gte.name + '. They can barely lift their weapon.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'leech-brew') {
    if (!DS.inCombat) { say('Use this in combat.'); return; }
    DS._leechTurns = item.leechTurns || 4;
    DS._leechPct = item.leechPct || 0.30;
    DS.inventory.splice(i, 1);
    addLog('🩸 Leech Brew! Every hit heals you for 30% of damage dealt for 4 turns.');
    say('Leech Brew active. 30% life steal for 4 turns.');
    setEvent('good', '🩸 Leech Brew — your attacks drain life for 4 turns.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'rage-tonic') {
    if (!DS.inCombat) { say('Use this in combat.'); return; }
    DS._rageTurns = item.rageTurns || 3;
    DS.inventory.splice(i, 1);
    addLog('💢 Rage Tonic! Triple ATK but double incoming damage for 3 turns. Pure chaos.');
    say('Rage Tonic! Triple damage dealt, double damage taken for 3 turns.');
    setEvent('good', '💢 RAGE TONIC — everything hurts more. Everything you do hurts more too.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'fog-flask') {
    var ffe = DS.enemy;
    if (!ffe) { say('No enemy to target.'); return; }
    DS._fogTurns = item.fogTurns || 3;
    DS.inventory.splice(i, 1);
    addLog('🌫️ Fog Flask! ' + ffe.name + ' accuracy drops 70% for 3 turns.');
    say('Fog Flask! Enemy 70% chance to miss for 3 turns.');
    setEvent('good', '🌫️ Thick fog surrounds ' + ffe.name + '. They can barely see you.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'time-potion') {
    if (!DS.inCombat) { say('Use this in combat.'); return; }
    DS._timeStop = (DS._timeStop || 0) + (item.freeAttacks || item.timeTurns || 2);
    DS.inventory.splice(i, 1);
    addLog('⌛ Time Potion! Time slows. You get 2 free attacks. Enemy cannot respond.');
    say('Time Potion! 2 free attacks. Enemy frozen.');
    setEvent('good', '⌛ Time bends around you. 2 free attacks incoming.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'corruption-flask') {
    var cfe = DS.enemy;
    if (!cfe) { say('No enemy to target.'); return; }
    DS._corruptionFlask = { turns: item.corrTurns || 4, dmgPerTurn: item.corrDmg || 20 };
    DS.inventory.splice(i, 1);
    addLog('💜 Corruption Flask! ' + cfe.name + ' takes 20 corruption damage each turn for 4 turns.');
    say('Corruption Flask! Enemy takes 20 damage per turn for 4 turns.');
    setEvent('good', '💜 Corruption seeps into ' + cfe.name + '. They will not last long.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();

  } else if (item.type === 'seasonal-buff') {
    var sb = item.buff, sbMsg = '';
    if (sb === 'stout') { DS.hp = Math.min(DS.maxHp, DS.hp + 50); fxTempStat('atk', -3, 2); sbMsg = 'Irish Stout! +50 HP, -3 attack for 2 turns.'; }
    else if (sb === 'crit') { DS.markedKill = true; sbMsg = item.name + '! Your next attack is a guaranteed critical.'; }
    else if (sb === 'shield') { DS.manaShield = (DS.manaShield || 0) + (item.amount || 40); sbMsg = item.name + '! Absorbs the next ' + (item.amount || 40) + ' damage.'; }
    else if (sb === 'rose') { fxTempStat('atk', 8, 4); sbMsg = 'Enchanted Rose! +8 attack for 4 turns.'; }
    DS.inventory.splice(i, 1);
    addLog(item.icon + ' ' + sbMsg); say(sbMsg);
    updatePlayerBar(); updateTopBar(); renderInv(); saveProgress();
    if (DS.inCombat) { setCombatBtns(true); updateSkillButtons(); }
  } else if (item.type === 'cannon') {
    // The Patriot Cannon could never be used
    var ce2 = DS.enemy;
    if (!DS.inCombat || !ce2) { say('Use the Patriot Cannon in combat.'); return; }
    if (ce2.isBoss) { say('The Patriot Cannon cannot defeat a boss.'); return; }
    DS.inventory.splice(i, 1);
    ce2.hp = 0; updateEnemyBar(); sfx('sfx-trap');
    addLog('💣 PATRIOT CANNON! ' + ce2.name + ' is blasted away!');
    say('Patriot Cannon! ' + ce2.name + ' is defeated.');
    renderInv(); saveProgress();
    setTimeout(function(){ enemyDead(); }, 400);
  } else if (item.type === 'love-potion') {
    // (it just ended the fight; the charmed enemy now strikes itself for 2 turns)
    var lpe = DS.enemy;
    if (!lpe) { say('No enemy to charm.'); return; }
    if (lpe.isBoss) { say('Bosses cannot be charmed. Their will is too strong.'); return; }
    fxGet().controlled = Math.max(fxGet().controlled || 0, 2);
    DS.inventory.splice(i, 1);
    addLog('💘 Love Potion! ' + lpe.name + ' is charmed — it will strike itself for 2 turns.');
    say('Love Potion! ' + lpe.name + ' is charmed and will strike itself for 2 turns.');
    renderInv(); saveProgress(); setCombatBtns(true); updateSkillButtons();
    return;
    DS._charmedAlly = { name: lpe.name, icon: lpe.icon || '💘', atk: lpe.atk, turns: 2 };
    var charmedEnemyName = lpe.name;
    DS.inventory.splice(i, 1);
    addLog('💘 Love Potion used on ' + charmedEnemyName + '! It falls in love with you and will fight for you for 2 turns.');
    say('Love Potion! ' + charmedEnemyName + ' is charmed and will fight for you for 2 turns.');
    setEvent('good', '💘 ' + charmedEnemyName + ' looks at you with adoring eyes. For now, it fights by your side.');
    DS.inCombat = false; DS.enemy = null;
    showDgPanels(true, false, false);
    renderInv(); saveProgress();
    setTimeout(function(){ enterRoom(); }, 600);
  } else if (item.type === 'rune') {
    var runeDef = RUNE_DEFS.find(function(r){ return r.id === item.id; });
    if (runeDef) { runeDef.apply(); DS.inventory.splice(i,1); renderInv(); saveProgress(); updateTopBar(); }
    else say('Unknown rune.');
    setCombatBtns(true); updateSkillButtons(); return;
  } else if (item.type === 'scroll') {
    // Spell scroll — has a spellId. (This looked spells up in SPELLS, which
    // doesn't exist, so reading any spell scroll threw an error and did nothing.)
    if (item.spellId) {
      if (!DS.inCombat) {
        // A magic class with a Spell Book can try to learn it
        if (hasLearnedSpell(item.spellId)) {
          say('You already know ' + item.name + '. Sell it, or read it in combat for one cast.');
        } else if (hasSpellBookNow() && isMagicClass(DS.cls)) {
          DS.inventory.splice(i, 1);
          if (Math.random() < getSpellLearnChance(DS.cls)) {
            learnSpell(item.spellId);
            addLog('📜 ' + item.name + ' learned! Spell added to your book.');
            say(item.name + ' learned. Spell added to your book.');
          } else {
            addLog('📜 Failed to learn ' + item.name + '. The scroll dissolved.');
            say('Failed to learn ' + item.name + '. The scroll dissolved.');
          }
          renderInv(); saveProgress(); updateTopBar();
        } else {
          say(item.name + ' can be read in combat for one cast.' + (isMagicClass(DS.cls) ? ' With a Spell Book you could learn it.' : ''));
        }
      } else {
        // Read in combat: one cast, no cooldown
        DS.inventory.splice(i, 1);
        var _cdBefore = DS._spellCooldown || 0;
        castSpell(item.spellId);
        DS._spellCooldown = _cdBefore;
        renderInv(); saveProgress();
        if (DS.inCombat && DS.enemy && DS.enemy.hp > 0) { setCombatBtns(true); updateSkillButtons(); }
        return;
      }
      setCombatBtns(true); updateSkillButtons(); return;
    }
    // Regular scroll — Reveal, Smite, Mending, Knowledge
    var scrollDef = SCROLL_DEFS.find(function(s){ return s.id === item.id; });
    // Mending only heals outside combat; reading it in a fight used it up for nothing.
    if (scrollDef && scrollDef.id === 'scroll-mending' && DS.inCombat) { say('The Scroll of Mending only works outside combat. It is still in your bag.'); setCombatBtns(true); updateSkillButtons(); return; }
    if (scrollDef) { scrollDef.apply(); DS.inventory.splice(i,1); renderInv(); saveProgress(); updateTopBar(); }
    else say('Unknown scroll.');
    setCombatBtns(true); updateSkillButtons(); return;
  } else if (item.type === 'soul-trap') {
    if (!DS.inCombat) { say('You must be in combat to use a Soul Trap. Enter a fight first, then use it from your inventory.'); return; }
    var te = DS.enemy;
    if (!te) { say('No enemy to capture. Use a Soul Trap during combat.'); return; }
    if (te.isBoss) { say('You cannot capture bosses.'); return; }
    if (te.isTimeDescender) { say('The Time Descender cannot be captured. It must be fought.'); return; }
    if (te.isTutorialEnemy) { say('This is a training enemy — Soul Traps are not needed here.'); return; }
    // isElite was never passed, so every minion was common.
    var captured = captureMinion({ id: (te.id || te.name.toLowerCase().replace(/ /g,'_')), name: te.name, icon: te.icon || '👾', atk: te.atk ? (Array.isArray(te.atk) ? te.atk[1] : te.atk) : 5, isElite: !!te.isElite });
    if (captured) {
      DS.inventory.splice(i, 1);
      addLog('🪤 ' + te.name + ' captured as a minion!');
      te.hp = 0;
      renderInv(); saveProgress();
      setTimeout(function(){ enemyDead(); }, 400);
    }
    return;
  } else if (item.type === 'skill-orb') {
    useSkillOrb(item, i); return;
  } else if (item.type === 'enchanter') {
    say('Enchanter. ' + (item.charges||3) + ' charges remaining. Go to the Blacksmith and upgrade a weapon — the Enchanter will be used automatically instead of gold.');
    return;
  } else if (item.type === 'music-player') {
    useMusicPlayerItem();
    return;
  } else if (item.type === 'gamblers-spirit') {
    if (DS._gamblersUsed) { say("Gambler's Spirit already used this run."); return; }
    if (DS.inCombat) { say("Cannot gamble during combat."); return; }
    DS._gamblersUsed = true;
    DS.inventory.splice(i, 1);
    // Ask player: double or halve? — use accessible modal instead of confirm()
    var doubleAmt = DS.gold * 2;
    var halveAmt = Math.floor(DS.gold / 2);
    showChoiceModal(
      "🎲 Gambler's Spirit — Choose Your Fate",
      "Double your gold (" + DS.gold + " → " + doubleAmt + "g) or halve it (" + DS.gold + " → " + halveAmt + "g). No refunds.",
      [
        { label: "Double (" + doubleAmt + "g)", action: function() {
          DS.gold = doubleAmt;
          addLog("🎲 Gambler's Spirit — DOUBLED! " + DS.gold + " gold!");
          say("Gambler's Spirit. You doubled your gold. " + DS.gold + " gold.");
          setEvent('good', "🎲 Gambler's Spirit — Fortune smiles. Gold doubled!");
          updateTopBar(); saveProgress();
        }},
        { label: "Halve (" + halveAmt + "g)", action: function() {
          DS.gold = halveAmt;
          addLog("🎲 Gambler's Spirit — HALVED. " + DS.gold + " gold.");
          say("Gambler's Spirit. You halved your gold. " + DS.gold + " gold.");
          setEvent('danger', "🎲 Gambler's Spirit — The dice were cruel. Gold halved.");
          updateTopBar(); saveProgress();
        }}
      ]
    );
    renderInv();
    return;
  } else {
    say(item.name + '. ' + item.desc + ' This item is passive and already active.');
  }
}

// ── STATS ──
function showStats() {
  var overlay = document.getElementById('stats-overlay');
  if (!overlay) return;
  var skills = getUnlockedSkills();
  var allSkills = CLASS_SKILLS[DS.cls] || [];
  var dungeonShort = DS.dungeon === 'The Ashbound Wastes' ? 'Ashbound Wastes'
    : DS.dungeon === 'Frosthold Abyss' ? 'Frosthold Abyss'
    : DS.dungeon === 'The Sunken Archives' ? 'Sunken Archives'
    : DS.dungeon === 'The Hollow' ? 'The Hollow'
    : 'Crypt of Malachar';

  // Skills HTML
  var skillsHtml = '<div class="stats-section-title">Unlocked Skills (' + skills.length + ' of ' + allSkills.length + ')</div>';
  if (skills.length === 0) {
    skillsHtml += '<p style="font-size:0.78rem;color:var(--text-dim);font-style:italic;">No skills unlocked yet — level up to choose skills.</p>';
  } else {
    skillsHtml += '<div style="display:flex;flex-direction:column;gap:5px;margin-bottom:8px;">';
    skills.forEach(function(sk) {
      skillsHtml += '<div class="stats-skill-row">' +
        '<span class="stats-skill-name">' + sk.icon + ' ' + sk.name +
        ' <span style="font-size:0.58rem;color:var(--text-dim);">' + sk.tier + '</span></span>' +
        '<span class="stats-skill-cost">' + sk.spCost + ' SP</span></div>';
    });
    skillsHtml += '</div>';
  }

  // Spirit HTML
  var spiritHtml = '';
  if (DS.activeSpirit) {
    spiritHtml = '<div class="stats-section-title">Spirit Companion</div>' +
      '<div style="background:#0a0616;border:1px solid #3a1060;padding:10px 14px;margin-bottom:8px;">' +
      '<span style="font-size:1.2rem;">' + DS.activeSpirit.icon + '</span> ' +
      '<span style="font-family:Cinzel,serif;font-size:0.82rem;color:#c080f0;">' + DS.activeSpirit.name + '</span>' +
      '<div style="font-size:0.72rem;color:var(--text-dim);font-style:italic;margin-top:3px;">' + DS.activeSpirit.ability + '</div>' +
      '</div>';
  }

  // Inventory HTML
  var invHtml = '<div class="stats-section-title">Inventory (' + DS.inventory.length + ' items)</div>';
  if (DS.inventory.length === 0) {
    invHtml += '<p style="font-size:0.78rem;color:var(--text-dim);font-style:italic;">Empty satchel.</p>';
  } else {
    invHtml += '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px;">';
    DS.inventory.forEach(function(item) {
      invHtml += '<span style="background:var(--bg-stone);border:1px solid var(--border-dim);padding:4px 10px;font-family:Cinzel,serif;font-size:0.65rem;color:var(--ash);">' + item.icon + ' ' + item.name + '</span>';
    });
    invHtml += '</div>';
  }

  // Death log HTML
  var deathHtml = '';
  if (_charIdx !== null && CHARS[_charIdx] && CHARS[_charIdx].deathLog && CHARS[_charIdx].deathLog.length > 0) {
    deathHtml = '<div class="stats-section-title">Death Log</div>';
    CHARS[_charIdx].deathLog.forEach(function(d) {
      deathHtml += '<div class="stats-death-entry">' +
        '<div class="stats-death-floor">☠ Floor ' + d.floor + ' · Lv ' + (d.level||'?') + ' · ' + d.date + '</div>' +
        'Slain by ' + d.killedBy + ' — ' + d.kills + ' kills, ' + (d.gold||0) + 'g' +
        (d.bestDmg ? ', best hit: ' + d.bestDmg : '') +
        (d.spirit && d.spirit !== 'None' ? ', spirit: ' + d.spirit : '') +
        '<div style="font-size:0.7rem;color:var(--text-dim);font-style:italic;margin-top:3px;">' + (d.flavor||'') + '</div>' +
        '</div>';
    });
  }

  var xpNeeded = [0,100,220,380,580,820,1100,1430,1810,2240];
  overlay.querySelector('.stats-box').innerHTML =
    '<h2 class="stats-title">📊 ' + DS.name + '</h2>' +

    '<div class="stats-section-title">Character</div>' +
    '<div class="stats-grid-2">' +
      statBox('Class', DS.race + ' ' + DS.cls) +
      statBox('Profession', DS.prof) +
      statBox('Dungeon', dungeonShort) +
      statBox('Difficulty', DS.diff) +
    '</div>' +

    '<div class="stats-section-title">Combat Stats</div>' +
    '<div class="stats-grid-3">' +
      statBox('Level', 'Lv ' + DS.level) +
      statBox('XP', DS.xp + ' / ' + (DS.level < 10 ? xpNeeded[DS.level] : 'MAX')) +
      statBox('Floor', DS.floor + ' / 10') +
      statBox('HP', DS.hp + ' / ' + DS.maxHp) +
      statBox('SP', DS.sp + ' / ' + DS.maxSp) +
      statBox('Lives', DS.lives + ' / ' + DS.maxLives) +
      statBox('Attack', (DS.atk[0]+DS.atkBonus) + ' — ' + (DS.atk[1]+DS.atkBonus)) +
      statBox('Defense', String(DS.def + DS.defBonus)) +
      statBox('Gold', DS.gold + 'g') +
    '</div>' +

    '<div class="stats-section-title">Run Progress</div>' +
    '<div class="stats-grid-2">' +
      statBox('Enemies Slain', String(DS.kills)) +
      statBox('Potions Used', DS.usedPotion ? 'Yes' : 'None yet') +
      statBox('NG+', DS.ngPlus ? 'Active' : 'No') +
      statBox('Daily Challenge', DS.dailyChallenge ? DS.dailyChallenge : 'None') +
    '</div>' +

    spiritHtml +
    skillsHtml +
    invHtml +
    deathHtml +

    '<button class="btn-close" onclick="closeStatsOverlay()" aria-label="Close stats" style="width:100%;margin-top:12px;">← Close</button>';

  overlay.classList.add('open');
  say(DS.name + ' the ' + DS.race + ' ' + DS.cls + ' on ' + DS.diff +
    '. Level ' + DS.level + '. HP ' + DS.hp + ' of ' + DS.maxHp +
    '. SP ' + DS.sp + ' of ' + DS.maxSp +
    '. Attack ' + (DS.atk[0]+DS.atkBonus) + ' to ' + (DS.atk[1]+DS.atkBonus) +
    '. Defense ' + (DS.def+DS.defBonus) +
    '. Gold ' + DS.gold + '. Kills ' + DS.kills +
    '. Floor ' + DS.floor + ' of 10' +
    '. Skills unlocked: ' + skills.length + ' of ' + allSkills.length + '.');
  setTimeout(function(){ overlay.querySelector('.btn-close').focus(); }, 60);
}

// ── FLEE DUNGEON ──
function closeStatsOverlay() {
  document.getElementById('stats-overlay').classList.remove('open');
  say('Stats closed.');
}

function askFlee() {
  document.getElementById('ov-flee-text').textContent = DS.name + ' is on floor ' + DS.floor + '. Your progress will be saved and you can return later.';
  openOv('ov-flee');
  say('Flee dungeon? Press Flee to escape or Keep Fighting to continue. Your progress to floor ' + DS.floor + ' will be saved.');
}

function confirmFlee() {
  closeOv('ov-flee');
  try { resetGunState(); } catch(e) {}
  saveProgress();
  stopAmbient();
  playTrack(getMenuTrack());
  goTo('menu');
  say('You fled the dungeon. Progress saved at floor ' + DS.floor + '.');
}

// ── JOURNAL ──
function addJournalEntry(text) {
  if (!DS.journalLog) DS.journalLog = [];
  var now = new Date();
  var timeStr = (now.getMonth()+1)+'/'+now.getDate()+' Floor '+DS.floor;
  DS.journalLog.push({ time: timeStr, text: text });
}

// ── SAVE ──
function saveProgress(completed) {
  if (_charIdx === null) return;
  CHARS[_charIdx].floor = completed ? 10 : DS.floor;
  if (completed) {
    CHARS[_charIdx].completed = true;
    CHARS[_charIdx].midRunSave = null;
    trackGlobalStat('runsCompleted', 1);
    try { gainFamiliarBond(15); } catch(e2) {}

    // Unlock next dungeon globally
    var dungeonOrder = ['Crypt of Malachar','The Ashbound Wastes','Frosthold Abyss','The Sunken Archives','The Hollow','The Whispering Forest','The Infernal Descent','The Abyssal Deep'];
    var doneIdx = dungeonOrder.indexOf(DS.dungeon || CHARS[_charIdx].dungeon);
    if (doneIdx >= 0 && doneIdx < dungeonOrder.length - 1) {
      var unlocksData = _jsonParseSafe(DDStore.getItem('dd_unlocks'), '{}');
      unlocksData[dungeonOrder[doneIdx + 1]] = true;
      DDStore.setItem('dd_unlocks', JSON.stringify(unlocksData));
    }
    // Mark tutorial done after first clear
    markTutorialDone();
    // Track flawless run (no deaths this run)
    if (!(DS._diedThisRun)) updateAchievementStat('flawlessRuns', (getAchievementStats().flawlessRuns||0) + 1);
    // Track speed run (under 10 minutes)
    if (_runStartTime && (Date.now() - _runStartTime) < 600000) updateAchievementStat('speedRuns', (getAchievementStats().speedRuns||0) + 1);
    // Track unique classes won
    var wonClasses = _jsonParseSafe(DDStore.getItem('dd_won_classes'), '[]');
    if (DS.cls && wonClasses.indexOf(DS.cls) === -1) {
      wonClasses.push(DS.cls);
      DDStore.setItem('dd_won_classes', JSON.stringify(wonClasses));
      updateAchievementStat('uniqueClassesWon', wonClasses.length);
    }
    // Track dungeon specific completions
    if (DS.dungeon === 'The Whispering Forest') updateAchievementStat('whisperComplete', (getAchievementStats().whisperComplete||0) + 1);
    if (DS.dungeon === 'The Infernal Descent') {
      updateAchievementStat('infernalComplete', (getAchievementStats().infernalComplete||0) + 1);
      updateAchievementStat('infernalTrialWon', (getAchievementStats().infernalTrialWon||0) + 1);
    }
    if (DS.dungeon === 'The Abyssal Deep') { updateAchievementStat('abyssalComplete', (getAchievementStats().abyssalComplete||0) + 1); updateAchievementStat('abyssalBossDefeated', 1); if (DS.hardcoreMode) updateAchievementStat('abyssalHardcoreWin', 1); }
    // Transfer usable items from dungeon inventory to global inventory on run complete.
    // BUGFIX: this used to call addToGlobalInventory() once per item, each call
    // re-parsing/re-saving the whole global inventory array (O(n) work times n
    // items = O(n^2)) — punishing on a save with thousands of items. Merge in
    // memory once and save once instead. Dedup is still addToGlobalInventory()'s
    // job (singleton types, weapon/armor by name); this just batches the writes.
    if (DS.inventory && DS.inventory.length > 0) {
      var keepTypes = ['enchanter','soul-trap','music-player','skill-orb','rune','scroll','sp-potion'];
      var _globalInv = getGlobalInventory();
      var _singletonTypesSeen = {};
      _globalInv.forEach(function(i) {
        if (['music-player','enchanter','soul-trap','skill-orb'].indexOf(i.type) !== -1) _singletonTypesSeen[i.type] = true;
      });
      var _namedSeen = {};
      _globalInv.forEach(function(i) {
        if (i.type === 'weapon' || i.type === 'armor') _namedSeen[i.type + '::' + i.name] = true;
      });
      DS.inventory.forEach(function(item) {
        if (keepTypes.indexOf(item.type) === -1 && item.type !== 'weapon' && item.type !== 'armor') return;
        if (['music-player','enchanter','soul-trap','skill-orb'].indexOf(item.type) !== -1) {
          if (_singletonTypesSeen[item.type]) return;
          _singletonTypesSeen[item.type] = true;
        } else if (item.type === 'weapon' || item.type === 'armor') {
          var key = item.type + '::' + item.name;
          if (_namedSeen[key]) return;
          _namedSeen[key] = true;
        }
        _globalInv.push(item);
      });
      saveGlobalInventory(_globalInv);
      DS.inventory = [];
    }
    // Journal only ever persisted on death (see handleDeath()) — a run you
    // won or walked away from lost every journal entry it logged, since
    // saveJournal() existed but was never called from any other exit path.
    if (DS.journalLog) CHARS[_charIdx].journal = DS.journalLog;
    saveChars();
    checkAchievements();
    recordDungeonFirstClear(DS.dungeon, DS.name, DS.cls, DS.race);
    // Save persistent level on dungeon clear
    saveCharPersistentLevel(DS.level, DS.xp, DS.unlockedSkills, DS.maxHp, DS.atkBonus, _charIdx);
    checkLegends();
  } else {
    // Save full mid-run state so browser refresh / phone interruption can restore
    CHARS[_charIdx].midRunSave = {
      floor: DS.floor,
      hp: DS.hp, maxHp: DS.maxHp,
      sp: DS.sp, maxSp: DS.maxSp,
      gold: DS.gold,
      level: DS.level, xp: DS.xp,
      lives: DS.lives,
      kills: DS.kills,
      // Without this fight's own bonuses, which end with the fight
      atkBonus: DS.atkBonus - fxFightBonus('atk'), defBonus: DS.defBonus - fxFightBonus('def'), critBonus: (DS.critBonus||0) - ((DS._fx && DS._fx.fightCrit) || 0), luckBonus: (DS.luckBonus||0) - ((DS._fx && DS._fx.fightLuck) || 0), fleeBonus: (DS.fleeBonus||0) - ((DS._fx && DS._fx.fightFlee) || 0), _subclass: DS._subclass||null, _subclassName: DS._subclassName||null, _subclassIcon: DS._subclassIcon||null,
      inventory: DS.inventory,
      unlockedSkills: DS.unlockedSkills || [],
      skillPool: DS.skillPool || [],
      activeSpirit: DS.activeSpirit ? DS.activeSpirit.id : null,
      usedPotion: DS.usedPotion,
      ngPlus: DS.ngPlus,
      dailyChallenge: DS.dailyChallenge,
      roomsOnFloor: DS.roomsOnFloor,
      floorRoomsNeeded: DS.floorRoomsNeeded,
      _roomGraph: DS._roomGraph || null,
      _gridPos: DS._gridPos || null,
      journalLog: DS.journalLog ? DS.journalLog.slice(-50) : [],
      runLog: DS.runLog ? DS.runLog.slice(-100) : [],
      wepingChildSoothedThisRun: DS.wepingChildSoothedThisRun || false,
      // Equipped items — lost on restore without these
      equippedWeapon: DS.equippedWeapon || null,
      equippedArmor: DS.equippedArmor || null,
      // Dungeon and difficulty — critical for correct restore
      dungeon: DS.dungeon || null,
      diff: DS.diff || 'Normal',
      hardcoreMode: DS.hardcoreMode || false,
      // Key persistent combat/run flags
      _legendEchoShield: DS._legendEchoShield || false,
      _bloodPact: DS._bloodPact || false,
      _emberWard: DS._emberWard || false,
      _runeFortune: DS._runeFortune || false,
      _vampireLord: DS._vampireLord || false,
      // Tonight's conditions (they lived only in memory, so a resumed run re-rolled them)
      _weatherIds: { d: _dungeonWeather ? _dungeonWeather.id : null, a: _abyssalWeather ? _abyssalWeather.id : null, h: _hollowWeather ? _hollowWeather.id : null },
      _forestCorruption: (typeof _corruption !== 'undefined' && DS.dungeon === 'The Whispering Forest') ? _corruption : 0,
      _xpBoost: DS._xpBoost || null, _spiritBoost: DS._spiritBoost || 0, _sparklerAtk: !!DS._sparklerAtk,
      _bossRelicAtkBonus: DS._bossRelicAtkBonus || 0, _crownShieldActive: !!DS._crownShieldActive, _crownShieldUsed: !!DS._crownShieldUsed,
      _warlordAtk: DS._warlordAtk || 0, _tempAtk: DS._tempAtk || null, _tempDef: DS._tempDef || null,
      _skillMastery: DS._skillMastery || 0, _allMastery: DS._allMastery || 0, _halfCostSkills: !!DS._halfCostSkills,
      _debuffImmune: !!DS._debuffImmune, _onceSkills: DS._onceSkills || null, _bombReady: !!DS._bombReady, _beast: DS._beast || 0,
      _voidCurse: DS._voidCurse || false,
      _nightBlessing: DS._nightBlessing || false,
      hunterMode: DS.hunterMode || false,
      hunterAlive: DS.hunterAlive || false,
      hunterDistance: DS.hunterDist || 10,
    };
  }
  saveChars();
}

function hasMidRunSave(ch) {
  return ch && ch.midRunSave && !ch.completed && ch.midRunSave.floor >= 1;
}

function restoreMidRun(ch) {
  if (!hasMidRunSave(ch)) return false;
  var s = ch.midRunSave;
  // Init dungeon first to set base values
  initDungeon(ch);
  // Then restore saved state on top
  DS.floor = (s.floor && !isNaN(s.floor)) ? s.floor : 1;
  DS.hp = s.hp; DS.maxHp = s.maxHp;
  DS.sp = s.sp; DS.maxSp = s.maxSp;
  DS.gold = s.gold;
  DS.level = s.level; DS.xp = s.xp;
  var savedLives = s.lives != null ? s.lives : (LIVES_MAP[s.difficulty] || 1);
  var savedMaxLives = s.maxLives != null ? s.maxLives : (LIVES_MAP[s.difficulty] || 1);
  // Clamp — never load negative or zero lives on resume, minimum 1
  DS.lives = Math.max(1, savedLives);
  DS.maxLives = Math.max(1, savedMaxLives);
  DS.kills = s.kills;
  DS.atkBonus = s.atkBonus; DS.defBonus = s.defBonus;
  DS.critBonus = s.critBonus || 0;
  DS.luckBonus = s.luckBonus || 0;
  DS.fleeBonus = s.fleeBonus || 0;
  DS._subclass = s._subclass || null;
  DS._subclassName = s._subclassName || null;
  DS._subclassIcon = s._subclassIcon || null;
  // Same dedup cleanup as initDungeon() — a mid-run save can carry the same
  // accumulated weapon/armor/enchanter/soul-trap duplicates.
  DS.inventory = dedupeInventoryArray(s.inventory || []);
  DS.unlockedSkills = s.unlockedSkills || [];
  DS.skillPool = s.skillPool || [];
  DS.usedPotion = s.usedPotion || false;
  DS.ngPlus = s.ngPlus || false;
  DS.dailyChallenge = s.dailyChallenge || null;
  DS.roomsOnFloor = s.roomsOnFloor || 0;
  if (s.floorRoomsNeeded) DS.floorRoomsNeeded = s.floorRoomsNeeded;
  DS._roomGraph = s._roomGraph || null;
  DS._gridPos = s._gridPos || null;
  DS.journalLog = s.journalLog || [];
  DS.runLog = s.runLog || [];
  DS.wepingChildSoothedThisRun = s.wepingChildSoothedThisRun || false;
  // Restore equipped items
  DS.equippedWeapon = s.equippedWeapon || null;
  DS.equippedArmor  = s.equippedArmor  || null;
  // Restore dungeon and difficulty
  if (s.dungeon) DS.dungeon = s.dungeon;
  if (s.diff)    DS.diff    = s.diff;
  DS.hardcoreMode = s.hardcoreMode || false;
  // Restore persistent combat/run flags
  DS._legendEchoShield = s._legendEchoShield || false;
  DS._bloodPact        = s._bloodPact        || false;
  DS._emberWard        = s._emberWard        || false;
  DS._runeFortune      = s._runeFortune      || false;
  DS._vampireLord      = s._vampireLord      || false;
  DS._forestCorruptionSaved = s._forestCorruption || 0;
  if (s._weatherIds) {
    var _allDW = [];
    Object.keys(DUNGEON_WEATHER).forEach(function(k){ _allDW = _allDW.concat(DUNGEON_WEATHER[k] || []); });
    _dungeonWeather = s._weatherIds.d ? (_allDW.find(function(w){ return w.id === s._weatherIds.d; }) || null) : null;
    _abyssalWeather = s._weatherIds.a ? (ABYSSAL_WEATHER.find(function(w){ return w.id === s._weatherIds.a; }) || null) : null;
    _hollowWeather = s._weatherIds.h ? (HOLLOW_WEATHER.find(function(w){ return w.id === s._weatherIds.h; }) || null) : null;
  }
  if (DS._forestCorruptionSaved && typeof _corruption !== 'undefined') { _corruption = DS._forestCorruptionSaved; }
  DS._xpBoost = s._xpBoost || null; DS._spiritBoost = s._spiritBoost || 0; DS._sparklerAtk = !!s._sparklerAtk;
  DS._bossRelicAtkBonus = s._bossRelicAtkBonus || 0; DS._crownShieldActive = !!s._crownShieldActive; DS._crownShieldUsed = !!s._crownShieldUsed;
  DS._warlordAtk = s._warlordAtk || 0; DS._tempAtk = s._tempAtk || null; DS._tempDef = s._tempDef || null;
  DS._skillMastery = s._skillMastery || 0; DS._allMastery = s._allMastery || 0; DS._halfCostSkills = !!s._halfCostSkills;
  DS._debuffImmune = !!s._debuffImmune; DS._onceSkills = s._onceSkills || null; DS._bombReady = !!s._bombReady; DS._beast = s._beast || 0;
  restoreSubclassFlags();
  // The Gauntlet's progress lived only in memory, so leaving the app lost it.
  if (ch._gauntlet) { _gauntletActive = true; _gauntletProgress = ch._gauntlet.progress || 0; DS.lives = Math.min(DS.lives, 1); DS.maxLives = 1; }
  DS._voidCurse        = s._voidCurse        || false;
  DS._nightBlessing    = s._nightBlessing    || false;
  DS.hunterMode        = s.hunterMode        || false;
  DS.hunterAlive       = s.hunterAlive       || false;
  DS.hunterDist        = s.hunterDistance    || s.hunterDist || 10;
  // Restore spirit
  if (s.activeSpirit) {
    var sp = getSpiritById(s.activeSpirit);
    if (sp) { DS.activeSpirit = sp; updateSpiritDisplay(); }
  }
  return true;
}

// ── VICTORY ──
function showBossDeathCinematic(callback) {
  if (document.getElementById('boss-death-cinematic')) return;
  window._cinematicInProgress = true;
  window._cinematicStartedAt = Date.now();
  var bossName = DS.enemy ? DS.enemy.name : 'The Boss';
  var lines = [
    bossName + ' staggers.',
    'Falls to one knee.',
    'The dungeon shakes.',
    'And then — silence.',
    bossName + ' is defeated.'
  ];
  var ov = document.createElement('div');
  ov.id = 'boss-death-cinematic';
  ov.setAttribute('aria-live', 'assertive');
  ov.style.cssText = 'position:fixed;inset:0;background:#000;z-index:9000;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;';
  document.body.appendChild(ov);

  var delay = 0;
  lines.forEach(function(line, i) {
    setTimeout(function() {
      var el = document.createElement('div');
      el.style.cssText = 'font-family:Cinzel,serif;font-size:' + (i === lines.length-1 ? '1.2' : '0.9') + 'rem;color:' + (i === lines.length-1 ? '#e0c080' : '#666') + ';letter-spacing:0.2em;animation:cinematicFadeIn 0.8s ease;text-align:center;padding:0 20px;';
      el.textContent = line;
      ov.appendChild(el);
      say(line);
    }, delay);
    delay += 900;
  });

  setTimeout(function() {
    ov.style.animation = 'cinematicFadeOut 0.5s ease forwards';
    setTimeout(function() {
      if (ov.parentNode) ov.parentNode.removeChild(ov);
      window._cinematicInProgress = false;
      if (callback) callback();
    }, 500);
  }, delay + 400);
}

// ── TRUE ENDING ──
var ALL_DUNGEONS = [
  'Crypt of Malachar',
  'The Ashbound Wastes',
  'Frosthold Abyss',
  'The Sunken Archives',
  'The Hollow',
  'The Whispering Forest',
  'The Infernal Descent',
  'The Abyssal Deep'
];

function checkTrueEnding() {
  // Get all cleared dungeons from localStorage
  try {
    var cleared = _jsonParseSafe(DDStore.getItem('dd_cleared_dungeons'), '[]');
    // Add current dungeon
    if (DS.dungeon && cleared.indexOf(DS.dungeon) === -1) {
      cleared.push(DS.dungeon);
      DDStore.setItem('dd_cleared_dungeons', JSON.stringify(cleared));
    }
    // Check if all 8 cleared
    var allCleared = ALL_DUNGEONS.every(function(d) { return cleared.indexOf(d) !== -1; });
    if (allCleared && !DDStore.getItem('dd_true_ending_seen')) {
      return true;
    }
  } catch(e) {}
  return false;
}

function showTrueEnding() {
  DDStore.setItem('dd_true_ending_seen', '1');
  var ov = document.createElement('div');
  ov.id = 'true-ending-overlay';
  ov.setAttribute('role', 'dialog');
  ov.setAttribute('aria-modal', 'true');
  ov.setAttribute('aria-label', 'True Ending — Dungeon Master');
  ov.style.cssText = 'position:fixed;inset:0;background:#000;z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;overflow-y:auto;';

  var lines = [
    { text: 'They said the depths could not be conquered.', delay: 500 },
    { text: 'That the darkness was eternal.', delay: 2000 },
    { text: 'That no soul could survive what lay beneath.', delay: 3500 },
    { text: 'They were wrong.', delay: 5500 },
    { text: 'You descended into eight cursed dungeons.', delay: 7500 },
    { text: 'You faced the undead, the scorched, the frozen, the drowned,', delay: 9000 },
    { text: 'the hollow, the whispered, the infernal, and the abyssal.', delay: 10500 },
    { text: 'You faced every nightmare the dungeon could throw at you.', delay: 12000 },
    { text: 'And you are still standing.', delay: 14000 },
  ];

  var box = document.createElement('div');
  box.style.cssText = 'max-width:480px;width:100%;text-align:center;';
  ov.appendChild(box);
  document.body.appendChild(ov);

  // Animate lines one by one
  lines.forEach(function(l) {
    setTimeout(function() {
      var el = document.createElement('div');
      el.style.cssText = 'font-family:Cinzel,serif;font-size:0.82rem;color:#666;line-height:2;letter-spacing:0.05em;animation:cinematicFadeIn 1s ease;margin-bottom:4px;';
      el.textContent = l.text;
      box.appendChild(el);
      say(l.text);
    }, l.delay);
  });

  // Show title and buttons after all lines
  setTimeout(function() {
    var title = document.createElement('div');
    title.style.cssText = 'font-family:Cinzel,serif;font-size:2rem;color:#e0c080;margin:28px 0 8px;letter-spacing:0.2em;animation:cinematicFadeIn 1.5s ease;';
    title.textContent = 'DUNGEON MASTER';
    box.appendChild(title);
    say('Dungeon Master. The dungeon has a master now. And it is you.');

    var sub = document.createElement('div');
    sub.style.cssText = 'font-family:Cinzel,serif;font-size:0.68rem;color:#666;letter-spacing:0.3em;margin-bottom:32px;';
    sub.textContent = 'The dungeon has a master now. And it is you.';
    box.appendChild(sub);

    var btnRow = document.createElement('div');
    btnRow.style.cssText = 'display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:20px;';

    var credBtn = document.createElement('button');
    credBtn.type = 'button';
    credBtn.textContent = '📜 View Credits';
    credBtn.setAttribute('aria-label', 'View credits');
    credBtn.style.cssText = 'padding:14px 24px;background:#0a0800;border:1px solid #cc9944;color:#e0c080;font-family:Cinzel,serif;font-size:0.75rem;cursor:pointer;';
    credBtn.onclick = function() { document.getElementById('true-ending-overlay').remove(); goTo('credits'); };
    btnRow.appendChild(credBtn);

    var homeBtn = document.createElement('button');
    homeBtn.type = 'button';
    homeBtn.textContent = '🏠 Return Home';
    homeBtn.setAttribute('aria-label', 'Return to main menu');
    homeBtn.style.cssText = 'padding:14px 24px;background:#080808;border:1px solid #444;color:#888;font-family:Cinzel,serif;font-size:0.75rem;cursor:pointer;';
    homeBtn.onclick = function() { document.getElementById('true-ending-overlay').remove(); goHome(); };
    btnRow.appendChild(homeBtn);

    box.appendChild(btnRow);
    setTimeout(function() { credBtn.focus(); }, 100);
  }, 16000);
}

// ── END TRUE ENDING ──

function _continueBossVictory() {
  showVictory();
}

function showVictory() {
  DS._victoryPending = false;
  vibe(VIBE.bossKill);
  setTimeout(companionOnVictory, 800);
  medusaStillLooksCheck();
  DS.inCombat = false;
  DS.enemy = null;
  setCombatBtns(false);
  stopBossTimer();
  showDgPanels(true, false, false); // show exploration, not combat
  stopAmbient();
  stopInsaneMode();

  // ── GAUNTLET: chain to next dungeon ──
  if (_gauntletActive) {
    _gauntletProgress++;
    if (_gauntletProgress < GAUNTLET_DUNGEONS.length) {
      var nextDungeon = GAUNTLET_DUNGEONS[_gauntletProgress];
      var ch = CHARS[_charIdx];
      if (ch) {
        ch.dungeon = nextDungeon;
        ch.floor = 1;
        ch.midRunSave = null;
        ch._gauntlet = { progress: _gauntletProgress };
        // Keep current HP — no healing between dungeons
        ch._gauntletHp = DS.hp;
        ch._gauntletMaxHp = DS.maxHp;
        saveChars();
      }
      say('Dungeon ' + _gauntletProgress + ' cleared! Entering ' + nextDungeon + '. ' + (GAUNTLET_DUNGEONS.length - _gauntletProgress) + ' dungeons remain. HP carries over.');
      setTimeout(function() {
        initDungeon(ch);
        gauntletOneLife();
        challengeFixEndless();
        // Restore HP from previous dungeon
        if (ch._gauntletHp) { DS.hp = ch._gauntletHp; DS.maxHp = ch._gauntletMaxHp; updatePlayerBar(); }
        goTo('dungeon');
      }, 2000);
      return;
    } else {
      // Gauntlet complete!
      endGauntlet();
      // Award achievement
      var gAch = getAchievementStats();
      gAch.gauntletClears = (gAch.gauntletClears||0) + 1;
      saveAchievementStats(gAch);
      awardAchievement('gauntlet_champion');
      DDStore.setItem('dd_gauntlet_best', Date.now());
      say('THE GAUNTLET IS COMPLETE! All 6 dungeons cleared. You are the Gauntlet Champion.');
    }
  }

  // ── DAILY DUNGEON: save completion time ──
  if (DS._dailyRun && DS._dailyRunKey) {
    var elapsed = Math.round((Date.now() - DS._dailyRunStart) / 1000);
    var mins = Math.floor(elapsed / 60);
    var secs = elapsed % 60;
    var timeStr = mins + 'm ' + (secs < 10 ? '0' : '') + secs + 's';
    var existing = DDStore.getItem(DS._dailyRunKey);
    if (!existing) {
      DDStore.setItem(DS._dailyRunKey, timeStr);
      var ach = getAchievementStats();
      ach.dailyDungeonClears = (ach.dailyDungeonClears||0) + 1;
      saveAchievementStats(ach);
      awardAchievement('ach-daily-dungeon');
      say('Daily Dungeon complete! Time: ' + timeStr + '. Come back tomorrow for a new challenge.');
    }
    DS._dailyRun = false;
  }

  playTrack(getMenuTrack());

  // ── LEGACY MODE: increment dungeon tier on completion ──
  if (_charIdx !== null && CHARS[_charIdx]) {
    var ch = CHARS[_charIdx];
    if (ch.runMode === 'legacy') {
      ch.dungeonTier = (ch.dungeonTier || 1) + 1;
      saveChars();
      var tierMsg = 'Legacy Mode — Dungeon Tier ' + ch.dungeonTier + ' unlocked! Enemies will be stronger next run, but so will the rewards.';
      setEvent('good', tierMsg);
      say(tierMsg);
    }
  }

  try {
    buildRunSummary(true);
    goTo('runsummary');
  } catch(e2) {
    console.error('Victory screen error:', e2.message, e2.stack);
    try { goTo('runsummary'); } catch(e3) {
      goTo('menu');
      say('Dungeon cleared! Returning to menu.');
    }
  }

  // Track cleared dungeon and check true ending — outside try/catch so it always runs
  try {
    var _ve_cleared = _jsonParseSafe(DDStore.getItem('dd_cleared_dungeons'), '[]');
    if (DS.dungeon && _ve_cleared.indexOf(DS.dungeon) === -1) {
      _ve_cleared.push(DS.dungeon);
      DDStore.setItem('dd_cleared_dungeons', JSON.stringify(_ve_cleared));
    }
    if (checkTrueEnding()) {
      setTimeout(function() { showTrueEnding(); }, 3000);
    }
  } catch(e) { console.warn('[DD] True ending check failed:', e); }

  return;
  document.getElementById('dg-end').style.display = '';
  document.getElementById('dg-end-icon').textContent = '👑';
  var t = document.getElementById('dg-end-title');
  var isAsh   = DS.dungeon === 'The Ashbound Wastes';
  var isFrost = DS.dungeon === 'Frosthold Abyss';
  var bossName = DS.enemy ? DS.enemy.name : (isAsh ? 'The Eternal Pyre' : isFrost ? 'The Eternal Winter' : 'Malachar the Undying');
  var isNightmare = DS.diff === 'Nightmare';
  t.className = 'dg-end-title victory';
  t.textContent = isNightmare ? 'The Nightmare Ends' : isAsh ? 'The Pyre is Extinguished' : isFrost ? 'The Cold Breaks' : bossName + ' Falls';
  document.getElementById('dg-end-sub').textContent = isNightmare
    ? DS.name + ' has defeated ' + bossName + '. The nightmare recedes. Whatever it was, it will not forget you.'
    : isAsh
    ? DS.name + ' has defeated ' + bossName + '. The Ashbound Wastes fall silent for the first time in a thousand years.'
    : isFrost
    ? DS.name + ' has defeated ' + bossName + '. The Frosthold Abyss is still. The cold has finally, impossibly, broken.'
    : DS.name + ' has defeated ' + bossName + '. The Crypt is silent for the first time in a thousand years.';
  // Add victory quote
  var vQuoteEl = document.getElementById('dg-end-quote');
  if (!vQuoteEl) {
    vQuoteEl = document.createElement('div');
    vQuoteEl.id = 'dg-end-quote';
    vQuoteEl.className = 'dg-end-quote';
    vQuoteEl.style.borderLeftColor = 'var(--gold-dim)';
    document.getElementById('dg-end-sub').after(vQuoteEl);
  }
  vQuoteEl.textContent = getVictoryQuote();
  vQuoteEl.style.borderLeftColor = 'var(--gold-dim)';

  document.getElementById('dg-end-stats').innerHTML =
    eRow('Character', DS.name) + eRow('Class', DS.race + ' ' + DS.cls) +
    eRow('Profession', DS.prof) + eRow('Enemies Slain', DS.kills) +
    eRow('Gold', DS.gold + 'g') + eRow('Difficulty', DS.diff) +
    eRow('Level Reached', 'Lv ' + DS.level);
  document.getElementById('dg-retry-btn').textContent = 'Play Again';
  // Achievement tracking
  var achStats = getAchievementStats();
  incrementAchievementStat('dungeonsComplete', 1);
  // Track cleared dungeon for true ending
  try {
    var _cleared = _jsonParseSafe(DDStore.getItem('dd_cleared_dungeons'), '[]');
    if (DS.dungeon && _cleared.indexOf(DS.dungeon) === -1) {
      _cleared.push(DS.dungeon);
      DDStore.setItem('dd_cleared_dungeons', JSON.stringify(_cleared));
    }
    if (checkTrueEnding()) {
      setTimeout(function() { showTrueEnding(); }, 3000);
    }
  } catch(e) {}
  if (DS.diff==='Ironblood') incrementAchievementStat('ironbloodWins', 1);
  if (DS.diff==='Condemned') incrementAchievementStat('condemnedWins', 1);
  if (DS.dungeon==='Crypt of Malachar') incrementAchievementStat('cryptComplete', 1);
  if (DS.diff==='Forsaken')  incrementAchievementStat('forsakenWins', 1);
  if (DS.dungeon==='The Ashbound Wastes') incrementAchievementStat('ashboundComplete', 1);
  if (DS.dungeon==='Frosthold Abyss')     incrementAchievementStat('frostholdComplete', 1);
  if (DS.dungeon==='The Sunken Archives') incrementAchievementStat('sunkenComplete', 1);
  if (DS.dungeon==='The Hollow')          incrementAchievementStat('hollowComplete', 1);
  awardRareSpirit();
  updateDailyQuestProgress('boss', 1);
  if (DS.dungeon === 'The Hollow') updateDailyQuestProgress('hollow', 1);
  checkAchievements(); // Fire all completion achievements immediately
  // Track NG+ completion
  if (DS.ngPlus) {
    incrementAchievementStat('ngPlusComplete', 1);
    var ngCount = _charIdx !== null && CHARS[_charIdx] ? (CHARS[_charIdx].ngPlusCount || 1) : 1;
    if (ngCount >= 3) incrementAchievementStat('ngPlusMaxCount', ngCount);
  }
  // Track spirits earned
  if (_charIdx !== null && CHARS[_charIdx] && CHARS[_charIdx].earnedSpirits) {
    updateAchievementStat('spiritsEarned', CHARS[_charIdx].earnedSpirits.length);
  }
  // Track DDDI defeated
  if (DS.dddiDefeated) incrementAchievementStat('dddiDefeated', 1);
  // Mark market sprite as used if it was active this run
  // rare, elite or forged spirits all count (elite and forged ones were ignored)
  if (DS.activeSpirit && (DS.activeSpirit.rarity === 'rare' || DS.activeSpirit.rarity === 'elite' || DS.activeSpirit.isCustom || DS.activeSpirit.forged)) {
    updateDailyQuestProgress('rarespirit', 1);
  }
  if (DS.activeSpirit && DS.activeSpirit.isMarketSprite && _charIdx !== null) {
    CHARS[_charIdx].marketSpriteUsed = true;
    saveChars();
  }
  // Complete daily challenge on victory
  checkDailyChallengeCompletion();
  if (DS.diff==='Nightmare') {
    incrementAchievementStat('nightmareWins', 1);
    if (DS.enemy) {
      var nmKey = 'nm_' + DS.enemy.name.replace(/ /g,'_');
      var ns = getAchievementStats();
      if (!ns[nmKey]) { ns[nmKey]=true; ns.nightmareBossKills=(ns.nightmareBossKills||0)+1; saveAchievementStats(ns); checkAchievements(); }
    }
  }
  var unlockedSkills = getUnlockedSkills();
  if (unlockedSkills.length >= 5) updateAchievementStat('allSkillsUnlocked', true);
  // Track unique boss kills
  if (DS.enemy) {
    var bossKillKey = 'boss_' + DS.enemy.name.replace(/ /g,'_');
    var bs = getAchievementStats();
    if (!bs[bossKillKey]) { bs[bossKillKey]=true; bs.uniqueBossKills=(bs.uniqueBossKills||0)+1; saveAchievementStats(bs); checkAchievements(); }
  }
  // Show NG+ / Continue Journey button on run summary screen
  var ngBtn = document.getElementById('dg-ngplus-btn');
  if (ngBtn) ngBtn.style.display = '';
  var rsBtn = document.getElementById('rs-continue-journey-btn');
  if (rsBtn) rsBtn.style.display = '';

  speakCritical('Victory! You completed ' + (DS.dungeon||'the dungeon') + '. ' + DS.kills + ' enemies slain. ' + DS.gold + ' gold collected. Choose Continue to go to the next dungeon or New Game Plus to replay this one.');
  setTimeout(function() {
    var btn = document.getElementById('dg-ngplus-btn');
    if (btn) { btn.setAttribute('tabindex','0'); btn.focus(); }
  }, 300);
}

// ── BOSS RETRY ──
function showBossRetry() {
  try {
    var penalty = Math.floor((DS.gold || 0) * 0.15);
    var bossName = (DS.enemy && DS.enemy.name) ? DS.enemy.name : 'the Boss';
    var el = document.getElementById('boss-retry-overlay');
    if (!el) { showDefeat(); return; }
    var titleEl = document.getElementById('boss-retry-title');
    var msgEl   = document.getElementById('boss-retry-msg');
    var penEl   = document.getElementById('boss-retry-penalty-amt');
    if (titleEl) titleEl.textContent = 'Fallen Before ' + bossName;
    if (msgEl)   msgEl.textContent   = 'You were struck down, but the dungeon offers one final chance. Retry ' + bossName + ' with half your maximum HP. Your items stay with you. The boss resets to full strength.';
    if (penEl)   penEl.textContent   = penalty;
    // Store penalty and boss snapshot for retry
    DS._bossRetryPenalty = penalty;
    DS._bossRetryEnemy   = JSON.parse(JSON.stringify(DS.enemy)); // full boss snapshot
    el.style.display = 'flex';
    say('You fell before ' + bossName + '. Retry with half HP, or accept defeat. Gold penalty on retry: ' + penalty + ' gold.');
    var retryBtn = document.getElementById('boss-retry-btn');
    if (retryBtn) retryBtn.focus();
  } catch(e) {
    console.error('[BossRetry] showBossRetry failed:', e);
    try { showDefeat(); } catch(e2) {}
  }
}

function doBossRetry() {
  try {
    var el = document.getElementById('boss-retry-overlay');
    if (el) el.style.display = 'none';
    // Mark retry used so no second retry this run
    DS._bossRetryUsed = true;
    // Apply gold penalty
    var penalty = DS._bossRetryPenalty || 0;
    DS.gold = Math.max(0, (DS.gold || 0) - penalty);
    // Restore player HP to 50% max
    DS.hp = Math.max(1, Math.round(DS.maxHp * 0.50));
    DS.lives = 1;
    DS.inCombat = true;
    // Reset boss to full HP (phase 1)
    if (DS._bossRetryEnemy) {
      DS.enemy = JSON.parse(JSON.stringify(DS._bossRetryEnemy));
    }
    DS.bossPhase = 1;
    // Resume combat UI
    updatePlayerBar();
    updateEnemyBar();
    showDgPanels(false, true, false);
    setCombatBtns(true);
    updateTopBar();
    addLog('⚔ Boss Retry — ' + DS.enemy.name + ' resets. You fight on with ' + DS.hp + ' HP.');
    say('Retrying the boss. ' + DS.enemy.name + ' is at full strength. You have ' + DS.hp + ' of ' + DS.maxHp + ' HP. ' + penalty + ' gold lost.');
    vibe(VIBE.fight || [50, 100, 50]);
  } catch(e) {
    console.error('[BossRetry] doBossRetry failed:', e);
    try { showDefeat(); } catch(e2) {}
  }
}

function doBossRetryAccept() {
  try {
    var el = document.getElementById('boss-retry-overlay');
    if (el) el.style.display = 'none';
    showDefeat();
  } catch(e) {
    console.error('[BossRetry] doBossRetryAccept failed:', e);
  }
}

// ── DEFEAT ──
function showDefeat() {
  try { showDgPanels(false, false, false); } catch(e) {}
  try { stopAmbient(); } catch(e) {}
  try {
    // Track death count
    DS._diedThisRun = true;
    updateAchievementStat('totalDeaths', (getAchievementStats().totalDeaths||0) + 1);
  } catch(e) {}
  try {
    // Transfer keepable items to global inventory even on death
    if (DS.inventory && DS.inventory.length > 0) {
      var keepOnDeath = ['enchanter','soul-trap','music-player','skill-orb'];
      DS.inventory.forEach(function(item) {
        if (keepOnDeath.indexOf(item.type) !== -1 || item.type === 'weapon' || item.type === 'armor') {
          addToGlobalInventory(item);
        }
      });
    }
  } catch(e) {}
  try {
    // Save to graveyard on death
    if (_charIdx !== null && CHARS[_charIdx]) {
      var ch = CHARS[_charIdx];
      var entry = {
        name: ch.name, cls: ch.cls, race: ch.race,
        level: ch.persistLevel || ch.level || 1,
        dungeon: DS.dungeon || ch.dungeon,
        difficulty: DS.diff || ch.difficulty,
        killedBy: DS.enemy ? DS.enemy.name : 'unknown causes',
        topFloor: DS.floor || 1,
        journal: ch.journal || '',
        date: new Date().toLocaleDateString()
      };
      try {
        var g = getGraveyard();
        g.unshift(entry);
        if (g.length > 50) g = g.slice(0, 50);
        saveGraveyard(g);
      } catch(e) { console.warn('[Death graveyard]', e); }

      // Classic Mode — reset level to 1 on death
      if (!ch.runMode || ch.runMode === 'classic') {
        ch.persistLevel = 1;
        saveChars();
      }
      // Legacy Mode — keep level but reset dungeon tier to 1
      if (ch.runMode === 'legacy') {
        ch.dungeonTier = 1;
        saveChars();
      }

      // Post to global obituary
      try {
        postDeathToObituary({
          name: ch.name, cls: ch.cls,
          floor: DS.floor || 1,
          dungeon: DS.dungeon || 'Unknown',
          killedBy: DS.enemy ? DS.enemy.name : 'unknown causes',
          kills: DS.kills || 0,
          gold: DS.gold || 0,
          date: new Date().toLocaleDateString(),
          timestamp: Date.now()
        });
      } catch(e) { console.warn('[Death obituary]', e); }
    }
  } catch(e) {}

  // Show death cinematic first, then defeat screen
  showDeathCinematic(function() {
    try {
      buildRunSummary(false);
      goTo('runsummary');
    } catch(e) {
      console.error('[DD] Death screen failed:', e.message);
      try {
        document.querySelectorAll('.screen').forEach(function(s) { s.classList.remove('active'); });
        var rs = document.getElementById('screen-runsummary');
        if (rs) { rs.classList.add('active'); _currentScreen = 'runsummary'; }
        say('Run ended. Return to menu when ready.');
      } catch(e2) {}
    }
  });
  return;
  document.getElementById('dg-end').style.display = '';
  document.getElementById('dg-end-icon').textContent = '💀';
  var t = document.getElementById('dg-end-title');
  t.className = 'dg-end-title defeat';
  t.textContent = 'The Dark Claims You';

  // Dungeon-specific subtitle
  var subs = {
    'Crypt of Malachar':    DS.name + ' fell in the Crypt. Malachar noted the arrival.',
    'The Ashbound Wastes':  DS.name + ' was consumed by the Wastes. The fire did not notice.',
    'Frosthold Abyss':      DS.name + ' was swallowed by the Abyss. The cold closed over the gap.',
    'The Sunken Archives':  DS.name + ' drowned in the Archives. Their name has been catalogued.',
    'The Hollow':           DS.name + ' did not leave the Hollow. Something there is glad about this.',
  };
  var sub = DS.diff === 'Nightmare'
    ? DS.name + ' was taken by the Nightmare. It has been added to the collection.'
    : (subs[DS.dungeon] || DS.name + ' could not escape. The dungeon continues.');
  document.getElementById('dg-end-sub').textContent = sub;

  // Quote
  var quote = getDefeatQuote();
  var quoteEl = document.getElementById('dg-end-quote');
  if (!quoteEl) {
    quoteEl = document.createElement('div');
    quoteEl.id = 'dg-end-quote';
    quoteEl.className = 'dg-end-quote';
    document.getElementById('dg-end-sub').after(quoteEl);
  }
  quoteEl.textContent = quote;

  // Stats
  document.getElementById('dg-end-stats').innerHTML =
    eRow('Character', DS.name) +
    eRow('Class', DS.race + ' ' + DS.cls) +
    eRow('Profession', DS.prof) +
    eRow('Dungeon', DS.dungeon === 'The Ashbound Wastes' ? 'Ashbound' : DS.dungeon === 'Frosthold Abyss' ? 'Frosthold' : 'Crypt') +
    eRow('Fell on Floor', DS.floor + ' of 10') +
    eRow('Enemies Slain', DS.kills) +
    eRow('Gold at Death', DS.gold + 'g') +
    eRow('Best Hit', DS.bestDmgThisRun ? DS.bestDmgThisRun + ' damage' : 'None') +
    eRow('Spirit', DS.activeSpirit ? DS.activeSpirit.name : 'None') +
    eRow('Skills Unlocked', DS.unlockedSkills ? DS.unlockedSkills.length : 0) +
    eRow('Difficulty', DS.diff) +
    eRow('Level Reached', 'Lv ' + DS.level);

  // Journal preview — last 3 entries
  var journalEl = document.getElementById('dg-end-journal');
  if (!journalEl) {
    journalEl = document.createElement('div');
    journalEl.id = 'dg-end-journal';
    document.getElementById('dg-end-stats').after(journalEl);
  }
  if (DS.journalLog && DS.journalLog.length > 0) {
    var recent = DS.journalLog.slice(-3);
    journalEl.className = 'dg-end-journal-preview';
    journalEl.innerHTML = '<div class="dg-end-journal-title">📜 Final Journal Entries</div>' +
      recent.map(function(e){ return '<div class="dg-end-journal-entry">' + e.time + ' — ' + e.text + '</div>'; }).join('');
  } else {
    journalEl.innerHTML = '';
  }

  document.getElementById('dg-retry-btn').textContent = 'Rise Again';
  say('Defeated. ' + DS.name + ' fell on floor ' + DS.floor + '. ' + DS.kills + ' enemies slain. ' + quote + ' Press Rise Again to try again.');
  setTimeout(function() {
    var btn = document.getElementById('dg-retry-btn');
    if (btn) { btn.setAttribute('tabindex','0'); btn.focus(); }
  }, 300);
}

function eRow(k, v) {
  return '<div class="dg-end-row"><span class="dg-end-key">' + k + '</span><span class="dg-end-val">' + v + '</span></div>';
}

function statBox(label, value) {
  return '<div class="stat-box" tabindex="0" aria-label="' + label + ': ' + value + '">' +
    '<div class="stat-box-val">' + value + '</div>' +
    '<div class="stat-box-label">' + label + '</div>' +
  '</div>';
}

function retryRun() {
  if (_charIdx !== null) {
    CHARS[_charIdx].floor = 1;
    CHARS[_charIdx].midRunSave = null;
    saveChars();
    document.getElementById('dg-end').style.display = 'none';
    var ngBtn = document.getElementById('dg-ngplus-btn');
    if (ngBtn) ngBtn.style.display = 'none';
    initDungeon(CHARS[_charIdx]);
    say('Starting a new run as ' + DS.name + '.');
    setTimeout(function() { showQuestPopup(); }, 150);
  }
}


function openNGPlusChoice() {
  var ch = _charIdx !== null ? CHARS[_charIdx] : null;
  var dungeonOrder = ['Crypt of Malachar','The Ashbound Wastes','Frosthold Abyss','The Sunken Archives','The Hollow','The Whispering Forest','The Infernal Descent','The Abyssal Deep','The Shadow World'];
  var currentIdx = dungeonOrder.indexOf(ch ? ch.dungeon : '');
  var nextDungeon = (currentIdx >= 0 && currentIdx < dungeonOrder.length - 1) ? dungeonOrder[currentIdx + 1] : null;

  // Update modal text
  var sub = document.getElementById('ngplus-choice-sub');
  if (sub) sub.textContent = (ch ? ch.name : 'Your character') + ' has conquered ' + (ch ? ch.dungeon : 'the dungeon') + '. What happens next?';

  // Update Continue Journey button — show next dungeon name or hide if last dungeon
  var nextBtn = document.getElementById('ngplus-choice-next');
  if (nextBtn) {
    if (nextDungeon) {
      nextBtn.style.display = '';
      nextBtn.setAttribute('aria-label', 'Continue Journey to ' + nextDungeon + ' with your current character');
      nextBtn.querySelector('span').textContent = 'Enter ' + nextDungeon + ' — your character carries over';
    } else {
      // Last dungeon — hide Continue Journey
      nextBtn.style.display = 'none';
    }
  }

  openOv('ov-ngplus-choice');
  // Focus Continue Journey button first so JAWS reads it
  setTimeout(function() {
    var btn = document.getElementById('ngplus-choice-next') || document.getElementById('ngplus-choice-ng');
    if (btn) btn.focus();
  }, 80);
  var msg = nextDungeon
    ? 'Journey continues. Choose your path. New Game Plus replays ' + (ch ? ch.dungeon : 'this dungeon') + ' with harder enemies. Continue Journey takes you to ' + nextDungeon + ' with your current character.'
    : 'You have conquered all dungeons. New Game Plus awaits. The dungeon dares you to return.';
  say(msg);
}

function continueJourney() {
  closeOv('ov-ngplus-choice');
  if (_charIdx === null) return;
  var ch = CHARS[_charIdx];
  var dungeonOrder = ['Crypt of Malachar','The Ashbound Wastes','Frosthold Abyss','The Sunken Archives','The Hollow','The Whispering Forest','The Infernal Descent','The Abyssal Deep','The Shadow World'];
  var currentIdx = dungeonOrder.indexOf(ch.dungeon);
  if (currentIdx < 0 || currentIdx >= dungeonOrder.length - 1) {
    // Last dungeon — nothing to continue to, just go to menu
    say('You have conquered all eight dungeons. The journey is complete.');
    goTo('menu');
    return;
  }
  var nextDungeon = dungeonOrder[currentIdx + 1];

  // Save XP and level before initDungeon resets them
  var savedXp    = DS.xp    || ch.xp    || 0;
  var savedLevel = DS.level || ch.level || 1;

  // Move character to next dungeon, keep everything else
  trackGlobalStat('runsCompleted', 1); // count the dungeon we just finished
  ch.dungeon = nextDungeon;
  ch.floor = 1;
  ch.completed = false;
  ch.midRunSave = null;
  ch.marketSpriteUsed = false;
  saveChars();

  document.getElementById('dg-end').style.display = 'none';
  var ngBtn = document.getElementById('dg-ngplus-btn');
  if (ngBtn) ngBtn.style.display = 'none';

  initDungeon(ch);

  // Restore XP and level — initDungeon resets these but they should carry over
  DS.xp    = savedXp;
  DS.level = savedLevel;
  updatePlayerBar();
  updateTopBar();

  // Navigate to dungeon screen — initDungeon doesn't do this itself
  goTo('dungeon');
  setTimeout(function(){ enterRoom(); }, 400);

  say('Journey continues. Entering ' + nextDungeon + '. Your character carries all their strength forward. The darkness deepens.');
}

function startNGPlus() {
  if (_charIdx === null) return;
  var ch = CHARS[_charIdx];
  ch.floor = 1;
  ch.ngPlus = true;
  ch.ngPlusCount = (ch.ngPlusCount || 0) + 1;
  ch.completed = false;
  ch.marketSpriteUsed = false; // reset market sprite for new run
  saveChars();
  document.getElementById('dg-end').style.display = 'none';
  var ngBtn = document.getElementById('dg-ngplus-btn');
  if (ngBtn) ngBtn.style.display = 'none';
  ch.ngPlusActive = true;
  initDungeon(ch);
  var ngNum = ch.ngPlusCount;
  var ngMsg = ngNum === 1 ? 'New Game Plus! Enemies are stronger. The dungeon has not forgotten you.'
    : ngNum === 2 ? 'NG+2! The dungeon is actively hostile now.'
    : ngNum >= 3 ? 'NG+' + ngNum + '! You should not still be alive. The dungeon is impressed and furious.'
    : 'New Game Plus started!';
  say(ngMsg);
}

function endReturn() {
  // Reset character to floor 1 so they are ready for a new run
  if (_charIdx !== null && CHARS[_charIdx]) {
    CHARS[_charIdx].floor = 1;
    CHARS[_charIdx].midRunSave = null;
    saveChars();
  }
  document.getElementById('dg-end').style.display = 'none';
  stopAmbient();
  playTrack(getMenuTrack());
  goTo('charlist');
  say('Returned to character selection. Your character has been saved.');
}

function endNewGame() {
  // Delete character and go to creation screen
  if (_charIdx !== null) {
    var name = CHARS[_charIdx] ? CHARS[_charIdx].name : 'Unknown';
    CHARS.splice(_charIdx, 1);
    saveChars();
    _charIdx = null;
    say(name + ' has been lost to the dark forever. Create a new character.');
  }
  document.getElementById('dg-end').style.display = 'none';
  stopAmbient();
  playTrack(getMenuTrack());
  goTo('creation');
}


